--
-- Name: add_maia_feedback(bigint, "text", "uuid", smallint, smallint, smallint, smallint, boolean, "text"[], "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."add_maia_feedback"("p_turn_id" bigint, "p_source_type" "text", "p_source_id" "uuid", "p_felt_seen_score" smallint, "p_attunement_score" smallint, "p_safety_score" smallint, "p_depth_score" smallint, "p_rupture_mark" boolean, "p_tags" "text"[], "p_comment" "text", "p_ideal_reply" "text") RETURNS bigint
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_feedback_id BIGINT;
BEGIN
  INSERT INTO maia_turn_feedback (
    turn_id,
    source_type,
    source_id,
    felt_seen_score,
    attunement_score,
    safety_score,
    depth_appropriateness_score,
    rupture_mark,
    tags,
    comment,
    ideal_maia_reply
  ) VALUES (
    p_turn_id,
    COALESCE(p_source_type, 'user'),
    p_source_id,
    p_felt_seen_score,
    p_attunement_score,
    p_safety_score,
    p_depth_score,
    COALESCE(p_rupture_mark, FALSE),
    COALESCE(p_tags, '{}'),
    p_comment,
    p_ideal_reply
  )
  RETURNING id INTO v_feedback_id;

  RETURN v_feedback_id;
END;
$$;


--
-- Name: archive_expired_room_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."archive_expired_room_events"() RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  UPDATE commons_room_events
  SET retention_status = 'archived',
      updated_at = now()
  WHERE expires_at IS NOT NULL
    AND expires_at < now()
    AND retention_status = 'active';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: archive_theme_on_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."archive_theme_on_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.theme_json IS DISTINCT FROM NEW.theme_json THEN
    INSERT INTO practitioner_theme_history (
      practitioner_id,
      version,
      theme_json,
      changed_by,
      change_reason
    ) VALUES (
      OLD.practitioner_id,
      OLD.version,
      OLD.theme_json,
      'system',
      'Auto-archived on update'
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: calculate_chain_continuity("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_chain_continuity"("p_user_id" "text") RETURNS double precision
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_total_score FLOAT := 0;
  v_count INT := 0;
  v_reinterpretation_count INT := 0;
  v_node_count INT := 0;
BEGIN
  -- Get weighted average of continuity scores
  SELECT
    COALESCE(AVG(continuity_score), 1.0),
    COUNT(*)
  INTO v_total_score, v_node_count
  FROM selflet_nodes
  WHERE user_id = p_user_id;

  -- Bonus for reinterpretations (shows integration work)
  SELECT COUNT(*) INTO v_reinterpretation_count
  FROM selflet_reinterpretations sr
  JOIN selflet_nodes sn ON sr.interpreting_selflet_id = sn.id
  WHERE sn.user_id = p_user_id;

  -- Add integration bonus (up to 0.2 extra)
  IF v_node_count > 1 THEN
    v_total_score := v_total_score + LEAST(0.2, v_reinterpretation_count::FLOAT / v_node_count * 0.1);
  END IF;

  RETURN LEAST(1.0, v_total_score);
END;
$$;


--
-- Name: calculate_decayed_confidence(numeric, "text", timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."calculate_decayed_confidence"("base_confidence" numeric, "memory_type" "text", "last_confirmed" timestamp with time zone, "formed_at" timestamp with time zone) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
    half_life_days INTEGER;
    reference_date TIMESTAMPTZ;
    days_elapsed NUMERIC;
    decay_factor NUMERIC;
BEGIN
    half_life_days := CASE memory_type
        WHEN 'preference' THEN 365
        WHEN 'boundary' THEN 365
        WHEN 'event' THEN 90
        WHEN 'dream' THEN 60
        WHEN 'pattern' THEN 180
        WHEN 'effective_practice' THEN 120
        WHEN 'ineffective_practice' THEN 60
        WHEN 'breakthrough_emergence' THEN 180
        ELSE 90
    END;

    reference_date := COALESCE(last_confirmed, formed_at);
    days_elapsed := EXTRACT(EPOCH FROM (NOW() - reference_date)) / 86400.0;
    decay_factor := POWER(2, -days_elapsed / half_life_days);

    RETURN GREATEST(0.3, base_confidence * decay_factor);
END;
$$;


--
-- Name: check_client_encryption_status("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."check_client_encryption_status"("p_practitioner_id" "uuid") RETURNS TABLE("total_clients" bigint, "encrypted_clients" bigint, "plaintext_only" bigint, "encryption_percentage" numeric)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*) as total_clients,
    COUNT(*) FILTER (WHERE name_enc IS NOT NULL) as encrypted_clients,
    COUNT(*) FILTER (WHERE name_enc IS NULL AND name IS NOT NULL) as plaintext_only,
    ROUND(
      COUNT(*) FILTER (WHERE name_enc IS NOT NULL)::NUMERIC /
      NULLIF(COUNT(*), 0) * 100, 2
    ) as encryption_percentage
  FROM practitioner_clients
  WHERE practitioner_id = p_practitioner_id;
END;
$$;


--
-- Name: check_commons_rate_limit("uuid", "uuid", integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."check_commons_rate_limit"("p_member_id" "uuid", "p_room_id" "uuid", "p_max_per_hour" integer DEFAULT 5, "p_max_per_day" integer DEFAULT 20, "p_join_cooldown_minutes" integer DEFAULT 5) RETURNS TABLE("allowed" boolean, "reason" character varying)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_row commons_rate_limits%ROWTYPE;
BEGIN
  -- Upsert rate limit row
  INSERT INTO commons_rate_limits (member_id, room_id)
  VALUES (p_member_id, p_room_id)
  ON CONFLICT (member_id, room_id) DO NOTHING;

  SELECT * INTO v_row
  FROM commons_rate_limits
  WHERE member_id = p_member_id
    AND room_id IS NOT DISTINCT FROM p_room_id
  FOR UPDATE;

  -- Reset hourly counter if window expired
  IF v_row.hour_window_start < date_trunc('hour', now()) THEN
    UPDATE commons_rate_limits
    SET events_this_hour = 0,
        hour_window_start = date_trunc('hour', now()),
        updated_at = now()
    WHERE id = v_row.id;
    v_row.events_this_hour := 0;
  END IF;

  -- Reset daily counter if window expired
  IF v_row.day_window_start < CURRENT_DATE THEN
    UPDATE commons_rate_limits
    SET events_today = 0,
        day_window_start = CURRENT_DATE,
        updated_at = now()
    WHERE id = v_row.id;
    v_row.events_today := 0;
  END IF;

  -- Check hourly limit
  IF v_row.events_this_hour >= p_max_per_hour THEN
    RETURN QUERY SELECT false, 'RATE_LIMITED_HOURLY'::VARCHAR(30);
    RETURN;
  END IF;

  -- Check daily limit
  IF v_row.events_today >= p_max_per_day THEN
    RETURN QUERY SELECT false, 'RATE_LIMITED_DAILY'::VARCHAR(30);
    RETURN;
  END IF;

  -- Check join cooldown
  IF v_row.last_leave_at IS NOT NULL
     AND v_row.last_leave_at > now() - (p_join_cooldown_minutes || ' minutes')::INTERVAL THEN
    RETURN QUERY SELECT false, 'JOIN_COOLDOWN'::VARCHAR(30);
    RETURN;
  END IF;

  -- Increment counters
  UPDATE commons_rate_limits
  SET events_this_hour = events_this_hour + 1,
      events_today = events_today + 1,
      updated_at = now()
  WHERE id = v_row.id;

  RETURN QUERY SELECT true, NULL::VARCHAR(30);
END;
$$;


--
-- Name: check_rate_limit(character varying, character varying, character varying, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."check_rate_limit"("p_identifier" character varying, "p_identifier_type" character varying, "p_endpoint" character varying, "p_max_attempts" integer DEFAULT 5, "p_window_minutes" integer DEFAULT 15) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_record auth_rate_limits%ROWTYPE;
  v_backoff_minutes INTEGER;
BEGIN
  -- Get or create record
  SELECT * INTO v_record
  FROM auth_rate_limits
  WHERE identifier = p_identifier
    AND identifier_type = p_identifier_type
    AND endpoint = p_endpoint;

  IF NOT FOUND THEN
    -- First attempt, create record
    INSERT INTO auth_rate_limits (identifier, identifier_type, endpoint)
    VALUES (p_identifier, p_identifier_type, p_endpoint);
    RETURN TRUE;
  END IF;

  -- Check if currently blocked
  IF v_record.blocked_until IS NOT NULL AND v_record.blocked_until > NOW() THEN
    RETURN FALSE;
  END IF;

  -- Reset if window expired
  IF v_record.first_attempt_at < NOW() - (p_window_minutes || ' minutes')::INTERVAL THEN
    UPDATE auth_rate_limits
    SET attempts = 1,
        first_attempt_at = NOW(),
        last_attempt_at = NOW(),
        blocked_until = NULL,
        updated_at = NOW()
    WHERE id = v_record.id;
    RETURN TRUE;
  END IF;

  -- Increment attempts
  UPDATE auth_rate_limits
  SET attempts = attempts + 1,
      last_attempt_at = NOW(),
      updated_at = NOW()
  WHERE id = v_record.id
  RETURNING * INTO v_record;

  -- Check if should block
  IF v_record.attempts >= p_max_attempts THEN
    -- Exponential backoff: 15min, 30min, 1hr, 2hr, 4hr...
    v_backoff_minutes := p_window_minutes * POWER(2, v_record.block_count);
    IF v_backoff_minutes > 240 THEN v_backoff_minutes := 240; END IF; -- Max 4 hours

    UPDATE auth_rate_limits
    SET blocked_until = NOW() + (v_backoff_minutes || ' minutes')::INTERVAL,
        block_count = block_count + 1,
        attempts = 0,
        first_attempt_at = NOW() + (v_backoff_minutes || ' minutes')::INTERVAL,
        updated_at = NOW()
    WHERE id = v_record.id;
    RETURN FALSE;
  END IF;

  RETURN TRUE;
END;
$$;


