--
-- Name: cleanup_commons_rate_limits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cleanup_commons_rate_limits"() RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  DELETE FROM commons_rate_limits
  WHERE updated_at < now() - INTERVAL '48 hours';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: cleanup_expired_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cleanup_expired_sessions"() RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM auth_sessions
  WHERE expires_at < NOW() OR revoked = TRUE AND revoked_at < NOW() - INTERVAL '7 days';
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


--
-- Name: cleanup_old_analysis_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cleanup_old_analysis_jobs"("days_old" integer DEFAULT 7) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_count INT;
BEGIN
  DELETE FROM comms_analysis_queue
  WHERE status = 'done'
    AND finished_at < NOW() - (days_old || ' days')::INTERVAL;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: cleanup_orphaned_practice_insights(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cleanup_orphaned_practice_insights"() RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  deleted_count integer;
BEGIN
  DELETE FROM practice_insights pi
  WHERE NOT EXISTS (SELECT 1 FROM practice_sessions ps WHERE ps.id = pi.session_id)
    AND NOT EXISTS (SELECT 1 FROM supervision_sessions ss WHERE ss.id = pi.session_id);

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


--
-- Name: cleanup_rate_limits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."cleanup_rate_limits"() RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM auth_rate_limits
  WHERE updated_at < NOW() - INTERVAL '24 hours'
    AND (blocked_until IS NULL OR blocked_until < NOW());
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$$;


--
-- Name: coach_shared_item_authorship_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."coach_shared_item_authorship_immutable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.offered_by_member_id IS DISTINCT FROM OLD.offered_by_member_id THEN
    RAISE EXCEPTION 'coach_client_shared_items.offered_by_member_id is write-once: '
                    'an offering cannot be reattributed to another person.';
  END IF;
  IF NEW.relationship_id IS DISTINCT FROM OLD.relationship_id THEN
    RAISE EXCEPTION 'coach_client_shared_items.relationship_id is write-once: '
                    'an offering cannot be moved into a different relationship.';
  END IF;
  RETURN NEW;
END;
$$;


