--
-- Name: compute_developmental_tier("date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."compute_developmental_tier"("birth" "date") RETURNS character varying
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  age_years INTEGER;
BEGIN
  IF birth IS NULL THEN RETURN NULL; END IF;
  age_years := EXTRACT(YEAR FROM age(CURRENT_DATE, birth));
  IF age_years < 13 THEN RETURN 'under13';
  ELSIF age_years <= 15 THEN RETURN 'tier2';
  ELSIF age_years <= 17 THEN RETURN 'tier3';
  ELSE RETURN 'adult';
  END IF;
END;
$$;


