--
-- Name: enforce_consent_revocation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_consent_revocation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- If consent is being revoked (was true, now false)
  IF OLD.client_consent_given = true AND NEW.client_consent_given = false THEN
    NEW.client_name := NULL;
    NEW.client_contact := NULL;
    NEW.client_name_shared := false;
    NEW.consent_recorded_at := NULL;
  END IF;

  -- If name sharing is being revoked (was true, now false)
  IF OLD.client_name_shared = true AND NEW.client_name_shared = false THEN
    NEW.client_name := NULL;
    NEW.client_contact := NULL;
  END IF;

  -- Enforce: name_shared requires consent
  IF NEW.client_name_shared = true AND NEW.client_consent_given = false THEN
    NEW.client_name_shared := false;
    NEW.client_name := NULL;
    NEW.client_contact := NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_phi_encryption(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_phi_encryption"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
  field_name TEXT;
  enc_column TEXT;
  plaintext_val TEXT;
  enc_val TEXT;
BEGIN
  -- Check each PHI field defined in TG_ARGV
  -- TG_ARGV contains pairs: field1, field2, ... (plaintext column names)
  FOR i IN 0..array_upper(TG_ARGV, 1) LOOP
    field_name := TG_ARGV[i];
    enc_column := field_name || '_enc';

    -- Get the values using dynamic SQL
    EXECUTE format('SELECT ($1).%I::text, ($1).%I::text', field_name, enc_column)
      INTO plaintext_val, enc_val
      USING NEW;

    -- If plaintext is provided but encrypted is not, reject
    IF plaintext_val IS NOT NULL AND enc_val IS NULL THEN
      RAISE EXCEPTION 'PHI enforcement: % requires encryption (% must not be NULL when % is set)',
        TG_TABLE_NAME, enc_column, field_name
        USING ERRCODE = 'data_exception';
    END IF;
  END LOOP;

  RETURN NEW;
END;
$_$;


