--
-- Name: enforce_record_consent_before_stream(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_record_consent_before_stream"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  ev RECORD;
BEGIN
  SELECT kind, participant_id, encounter_id INTO ev
    FROM encounter_consent_events WHERE id = NEW.consent_event_id;
  IF ev IS NULL THEN
    RAISE EXCEPTION 'R-A1: consent_event_id % does not exist', NEW.consent_event_id;
  END IF;
  IF ev.kind <> 'record' THEN
    RAISE EXCEPTION 'R-A1: media stream requires a record-consent event, got kind=%', ev.kind;
  END IF;
  IF ev.participant_id <> NEW.participant_id OR ev.encounter_id <> NEW.encounter_id THEN
    RAISE EXCEPTION 'R-A1: consent event participant/encounter mismatch for stream';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_rl_container_status_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_rl_container_status_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  valid_transitions JSONB := '{
    "inquiry": ["active", "declined", "referred_out"],
    "active": ["paused", "closing"],
    "paused": ["active", "closing"],
    "closing": ["completed", "referred_out"],
    "completed": [],
    "referred_out": [],
    "declined": []
  }'::jsonb;
  allowed TEXT[];
BEGIN
  -- Skip if status unchanged
  IF OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;

  -- Get allowed transitions
  SELECT ARRAY(SELECT jsonb_array_elements_text(valid_transitions->OLD.status::text))
  INTO allowed;

  -- Check if transition is allowed
  IF NOT (NEW.status::text = ANY(allowed)) THEN
    RAISE EXCEPTION 'Invalid status transition: % → %. Allowed: %',
      OLD.status, NEW.status, allowed;
  END IF;

  -- Auto-set start_at when moving to active
  IF NEW.status = 'active' AND OLD.status = 'inquiry' AND NEW.start_at IS NULL THEN
    NEW.start_at := NOW();
  END IF;

  -- Auto-set end_at when completing or referring out
  IF NEW.status IN ('completed', 'referred_out') AND NEW.end_at IS NULL THEN
    NEW.end_at := NOW();
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_soul_portrait_immutable_text(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_soul_portrait_immutable_text"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.published_at IS NOT NULL
     AND NEW.immutable_text IS DISTINCT FROM OLD.immutable_text THEN
    RAISE EXCEPTION 'soul_portraits.immutable_text is write-once after publish (portrait %)', OLD.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_stream_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_stream_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Terminal states are immutable: no field of a committed or canceled stream may change.
  IF OLD.status IN ('stopped','canceled') THEN
    RAISE EXCEPTION 'evidence-immutability: stream % is % and cannot be modified', OLD.id, OLD.status;
  END IF;
  -- Only legal transitions may occur.
  IF NEW.status <> OLD.status THEN
    IF NOT (
      (OLD.status = 'pending'   AND NEW.status = 'recording') OR
      (OLD.status = 'recording' AND NEW.status IN ('stopped','canceled'))
    ) THEN
      RAISE EXCEPTION 'stream-lifecycle: illegal transition % -> %', OLD.status, NEW.status;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_transcript_encryption(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."enforce_transcript_encryption"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Require text_enc on INSERT
  IF TG_OP = 'INSERT' THEN
    IF NEW.text_enc IS NULL THEN
      RAISE EXCEPTION 'PHI enforcement: text_enc required for new transcript segments. Set PHI_ENCRYPTION_KEY and ensure encryption is enabled.';
    END IF;
  END IF;

  -- Require text_enc on UPDATE (prevents clearing encrypted column)
  IF TG_OP = 'UPDATE' THEN
    IF NEW.text_enc IS NULL THEN
      RAISE EXCEPTION 'PHI enforcement: text_enc cannot be NULL. Encrypted column is required.';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


