--
-- Name: find_related_insights("text", "public"."vector", double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."find_related_insights"("target_user_id" "text", "query_embedding" "public"."vector", "similarity_threshold" double precision DEFAULT 0.6, "max_results" integer DEFAULT 10) RETURNS TABLE("insight_id" "uuid", "similarity_score" double precision, "insight_text" "text", "insight_type" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ci.id,
    1 - (ci.insight_embedding <=> query_embedding) as similarity,
    ci.insight_text,
    ci.insight_type,
    ci.created_at
  FROM conversation_insights ci
  WHERE ci.user_id = target_user_id
    AND ci.insight_embedding IS NOT NULL
    AND 1 - (ci.insight_embedding <=> query_embedding) >= similarity_threshold
  ORDER BY similarity DESC
  LIMIT max_results;
END;
$$;


--
-- Name: find_similar_sessions("text", "public"."vector", double precision, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."find_similar_sessions"("target_user_id" "text", "query_embedding" "public"."vector", "similarity_threshold" double precision DEFAULT 0.7, "max_results" integer DEFAULT 5) RETURNS TABLE("session_id" "uuid", "similarity_score" double precision, "conversation_themes" "text"[], "session_start" timestamp with time zone)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    usp.id,
    1 - (usp.session_embedding <=> query_embedding) as similarity,
    usp.conversation_themes,
    usp.session_start
  FROM user_session_patterns usp
  WHERE usp.user_id = target_user_id
    AND usp.session_embedding IS NOT NULL
    AND 1 - (usp.session_embedding <=> query_embedding) >= similarity_threshold
  ORDER BY similarity DESC
  LIMIT max_results;
END;
$$;


--
-- Name: fn_legacy_client_messages_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_legacy_client_messages_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_thread_id UUID;
  v_sender_type TEXT;
  v_urgency TEXT;
BEGIN
  -- Find or create thread for this client-practitioner pair
  SELECT id INTO v_thread_id
  FROM comms_threads
  WHERE client_id = NEW.client_id
    AND practitioner_id = NEW.practitioner_id
    AND domain = 'clinical'
    AND thread_type = 'between_session'
  LIMIT 1;

  IF v_thread_id IS NULL THEN
    INSERT INTO comms_threads (
      domain, thread_type, practitioner_id, client_id,
      participants, status
    ) VALUES (
      'clinical', 'between_session', NEW.practitioner_id, NEW.client_id,
      jsonb_build_object(
        'client', NEW.client_id::text,
        'practitioner', NEW.practitioner_id::text
      ),
      'active'
    )
    RETURNING id INTO v_thread_id;
  END IF;

  -- Map direction to sender_type
  v_sender_type := CASE NEW.direction
    WHEN 'client_to_practitioner' THEN 'client'
    WHEN 'practitioner_to_client' THEN 'practitioner'
    ELSE 'client'
  END;

  -- Map urgency
  v_urgency := CASE NEW.urgency
    WHEN 'not_urgent' THEN 'normal'
    WHEN 'time_sensitive' THEN 'time_sensitive'
    WHEN 'safety_concern' THEN 'safety_concern'
    ELSE 'normal'
  END;

  -- Insert into comms_messages
  INSERT INTO comms_messages (
    id, thread_id, sender_type, sender_id,
    channel_type, message_type, urgency,
    body, body_enc, body_enc_meta,
    is_quick_response, quick_response_type,
    reply_to_id, delivery_status, read_at,
    created_at, updated_at
  ) VALUES (
    COALESCE(NEW.id, gen_random_uuid()),
    v_thread_id,
    v_sender_type,
    CASE v_sender_type
      WHEN 'client' THEN NEW.client_id
      ELSE NEW.practitioner_id
    END,
    'in_app',
    COALESCE(NEW.message_type, 'reflection'),
    v_urgency,
    NEW.body,
    NEW.body_enc,
    NEW.body_enc_meta,
    COALESCE(NEW.is_quick_response, FALSE),
    NEW.quick_response_type,
    NEW.reply_to_id,
    CASE NEW.status
      WHEN 'read' THEN 'read'
      ELSE 'sent'
    END,
    NEW.read_at,
    COALESCE(NEW.created_at, NOW()),
    COALESCE(NEW.updated_at, NOW())
  );

  -- If safety concern, create safety flag
  IF NEW.urgency = 'safety_concern' THEN
    INSERT INTO comms_safety_flags (
      thread_id, message_id, severity, cues, source
    ) VALUES (
      v_thread_id,
      NEW.id,
      'red',
      ARRAY['client_flagged'],
      'client_flagged'
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: fn_legacy_client_messages_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_legacy_client_messages_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Update the comms_messages record
  UPDATE comms_messages SET
    body = NEW.body,
    body_enc = NEW.body_enc,
    body_enc_meta = NEW.body_enc_meta,
    delivery_status = CASE NEW.status
      WHEN 'read' THEN 'read'
      WHEN 'archived' THEN 'read'  -- no direct mapping, treat as read
      ELSE 'sent'
    END,
    read_at = NEW.read_at,
    updated_at = NOW()
  WHERE id = OLD.id;

  -- Handle safety_reviewed change
  IF NEW.safety_reviewed = TRUE AND OLD.safety_reviewed = FALSE THEN
    UPDATE comms_safety_flags SET
      acknowledged_at = COALESCE(NEW.safety_reviewed_at, NOW()),
      acknowledged_by = NEW.safety_reviewed_by
    WHERE message_id = OLD.id
      AND acknowledged_at IS NULL;
  END IF;

  RETURN NEW;
END;
$$;


