--
-- Name: fn_migrate_legacy_messages(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_migrate_legacy_messages"() RETURNS TABLE("threads_created" integer, "messages_migrated" integer, "safety_flags_created" integer)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_threads_created INT := 0;
  v_messages_migrated INT := 0;
  v_safety_flags_created INT := 0;
  v_thread_id UUID;
  rec RECORD;
BEGIN
  -- Loop through unique client-practitioner pairs
  FOR rec IN
    SELECT DISTINCT client_id, practitioner_id
    FROM client_messages
    WHERE client_id IS NOT NULL AND practitioner_id IS NOT NULL
  LOOP
    -- Create thread if doesn't exist
    INSERT INTO comms_threads (
      domain, thread_type, practitioner_id, client_id,
      participants, status, created_at
    )
    SELECT
      'clinical', 'between_session', rec.practitioner_id, rec.client_id,
      jsonb_build_object(
        'client', rec.client_id::text,
        'practitioner', rec.practitioner_id::text
      ),
      'active',
      MIN(cm.created_at)
    FROM client_messages cm
    WHERE cm.client_id = rec.client_id
      AND cm.practitioner_id = rec.practitioner_id
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_thread_id;

    IF v_thread_id IS NOT NULL THEN
      v_threads_created := v_threads_created + 1;
    ELSE
      -- Get existing thread ID
      SELECT id INTO v_thread_id
      FROM comms_threads
      WHERE client_id = rec.client_id
        AND practitioner_id = rec.practitioner_id
        AND domain = 'clinical'
        AND thread_type = 'between_session'
      LIMIT 1;
    END IF;

    -- Skip if still no thread (shouldn't happen)
    CONTINUE WHEN v_thread_id IS NULL;

    -- Migrate messages for this thread
    INSERT INTO comms_messages (
      id, thread_id, sender_type, sender_id,
      channel_type, message_type, urgency,
      body, body_enc, body_enc_meta,
      is_quick_response, quick_response_type,
      reply_to_id, delivery_status, read_at,
      created_at, updated_at
    )
    SELECT
      cm.id,
      v_thread_id,
      CASE cm.direction
        WHEN 'client_to_practitioner' THEN 'client'
        WHEN 'practitioner_to_client' THEN 'practitioner'
        ELSE 'client'
      END,
      CASE cm.direction
        WHEN 'client_to_practitioner' THEN cm.client_id
        ELSE cm.practitioner_id
      END,
      'in_app',
      COALESCE(cm.message_type, 'reflection'),
      CASE cm.urgency
        WHEN 'not_urgent' THEN 'normal'
        WHEN 'time_sensitive' THEN 'time_sensitive'
        WHEN 'safety_concern' THEN 'safety_concern'
        ELSE 'normal'
      END,
      cm.body,
      cm.body_enc,
      cm.body_enc_meta,
      COALESCE(cm.is_quick_response, FALSE),
      cm.quick_response_type,
      cm.reply_to_id,
      CASE cm.status
        WHEN 'read' THEN 'read'
        WHEN 'archived' THEN 'read'
        ELSE 'sent'
      END,
      cm.read_at,
      cm.created_at,
      cm.updated_at
    FROM client_messages cm
    WHERE cm.client_id = rec.client_id
      AND cm.practitioner_id = rec.practitioner_id
    ON CONFLICT (id) DO NOTHING;

    GET DIAGNOSTICS v_threads_created = ROW_COUNT;
    v_messages_migrated := v_messages_migrated + v_threads_created;
  END LOOP;

  -- Migrate safety concern logs to comms_safety_flags
  INSERT INTO comms_safety_flags (
    thread_id, message_id, severity, cues, source,
    acknowledged_at, acknowledged_by, review_note, created_at
  )
  SELECT
    t.id,
    scl.message_id,
    'red',
    ARRAY['client_flagged'],
    'client_flagged',
    scl.acknowledged_at,
    scl.acknowledged_by,
    scl.review_note,
    scl.created_at
  FROM safety_concern_logs scl
  JOIN comms_messages m ON m.id = scl.message_id
  JOIN comms_threads t ON t.id = m.thread_id
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_safety_flags_created = ROW_COUNT;

  RETURN QUERY SELECT v_threads_created, v_messages_migrated, v_safety_flags_created;
END;
$$;


--
-- Name: fn_migrate_legacy_policies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_migrate_legacy_policies"() RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_count INT;
BEGIN
  INSERT INTO comms_policies (
    practitioner_id, client_id, domain,
    check_days, check_window_start, check_window_end, timezone,
    max_response_hours, crisis_copy,
    allow_inbound, allow_outbound, is_active,
    created_at, updated_at
  )
  SELECT
    mp.practitioner_id,
    mp.client_id,
    'clinical',
    mp.check_days,
    mp.check_window_start,
    mp.check_window_end,
    COALESCE(mp.timezone, 'America/New_York'),
    COALESCE(mp.max_response_hours, 48),
    mp.crisis_copy,
    COALESCE(mp.allow_client_messages, TRUE),
    COALESCE(mp.allow_practitioner_reply, TRUE),
    COALESCE(mp.is_active, TRUE),
    mp.created_at,
    mp.updated_at
  FROM message_policies mp
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: fn_requeue_stale_comms_jobs(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_requeue_stale_comms_jobs"("p_stale_after" interval DEFAULT '00:05:00'::interval) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_requeued INTEGER := 0;
BEGIN
  UPDATE comms_analysis_queue
  SET status = 'queued',
      started_at = NULL,
      finished_at = NULL,
      heartbeat_at = NULL,
      claimed_by = NULL,
      claimed_at = NULL
  WHERE status = 'processing'
    AND COALESCE(heartbeat_at, started_at, queued_at) < NOW() - p_stale_after;

  GET DIAGNOSTICS v_requeued = ROW_COUNT;
  RETURN v_requeued;
END;
$$;


--
-- Name: fn_requeue_stale_media_jobs(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_requeue_stale_media_jobs"("stale_threshold" interval) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE requeued INTEGER;
BEGIN
  UPDATE media_jobs
  SET status = 'queued', claimed_by = NULL, claimed_at = NULL,
      heartbeat_at = NULL, started_at = NULL
  WHERE status = 'processing'
    AND heartbeat_at < NOW() - stale_threshold
    AND attempts < max_attempts;
  GET DIAGNOSTICS requeued = ROW_COUNT;
  RETURN requeued;
END;
$$;


--
-- Name: fn_requeue_stale_summary_jobs(interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."fn_requeue_stale_summary_jobs"("stale_after" interval) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  requeued INT;
BEGIN
  WITH stale AS (
    UPDATE session_summary_queue
    SET status = 'queued',
        claimed_by = NULL,
        claimed_at = NULL,
        heartbeat_at = NULL,
        started_at = NULL
    WHERE status = 'processing'
      AND claimed_at < NOW() - stale_after
    RETURNING id
  )
  SELECT COUNT(*) INTO requeued FROM stale;
  RETURN requeued;
END;
$$;


--
-- Name: generate_encryption_salt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."generate_encryption_salt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Generate a 64-character hex string (32 bytes)
  NEW.encryption_key_salt := encode(gen_random_bytes(32), 'hex');
  NEW.encryption_key_version := 1;
  RETURN NEW;
END;
$$;


--
-- Name: get_active_field_movements(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_active_field_movements"("min_count" integer DEFAULT 3) RETURNS TABLE("movement_type" "text", "movement_description" "text", "participant_count" bigint)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  total_breakthroughs bigint;
  effective_min_count integer;
BEGIN
  -- Warmup mode: if field is sparse, lower the threshold
  SELECT COUNT(*) INTO total_breakthroughs FROM collective_breakthroughs WHERE created_at >= NOW() - INTERVAL '30 days';

  -- If total < 20, use min_count of 1 for early responsiveness
  -- Otherwise use the requested min_count (default 3)
  effective_min_count := CASE WHEN total_breakthroughs < 20 THEN 1 ELSE min_count END;

  -- Elemental transitions
  RETURN QUERY
  SELECT
    'elemental_transition'::TEXT,
    elemental_phase_from || ' → ' || elemental_phase_to,
    COUNT(*)
  FROM collective_breakthroughs
  WHERE created_at >= NOW() - INTERVAL '30 days'
    AND elemental_phase_from IS NOT NULL
    AND elemental_phase_to IS NOT NULL
  GROUP BY elemental_phase_from, elemental_phase_to
  HAVING COUNT(*) >= effective_min_count;

  -- Archetypal shifts
  RETURN QUERY
  SELECT
    'archetypal_shift'::TEXT,
    archetype_from || ' → ' || archetype_to,
    COUNT(*)
  FROM collective_breakthroughs
  WHERE created_at >= NOW() - INTERVAL '30 days'
    AND archetype_from IS NOT NULL
    AND archetype_to IS NOT NULL
  GROUP BY archetype_from, archetype_to
  HAVING COUNT(*) >= effective_min_count;
END;
$$;


--
-- Name: get_current_selflet("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_current_selflet"("p_user_id" "text") RETURNS TABLE("id" "uuid", "phase" character varying, "element" character varying, "archetypes" "text"[], "dominant_emotions" "text"[], "continuity_score" double precision, "created_at" timestamp with time zone, "essence_summary" "text")
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    sn.id,
    sn.phase,
    sn.element,
    sn.archetypes,
    sn.dominant_emotions,
    sn.continuity_score,
    sn.created_at,
    sn.essence_summary
  FROM selflet_nodes sn
  WHERE sn.user_id = p_user_id
    AND sn.active_until IS NULL
  ORDER BY sn.created_at DESC
  LIMIT 1;
END;
$$;


--
-- Name: get_pending_selflet_messages("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_pending_selflet_messages"("p_user_id" "text") RETURNS TABLE("message_id" "uuid", "from_phase" character varying, "from_element" character varying, "message_type" character varying, "title" character varying, "content" "text", "symbolic_objects" "text"[], "ritual_trigger" character varying, "relevance_themes" "text"[], "from_created_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    sm.id as message_id,
    sn_from.phase as from_phase,
    sn_from.element as from_element,
    sm.message_type,
    sm.title,
    sm.content,
    sm.symbolic_objects,
    sm.ritual_trigger,
    sm.relevance_themes,
    sn_from.created_at as from_created_at
  FROM selflet_messages sm
  JOIN selflet_nodes sn_from ON sm.from_selflet_id = sn_from.id
  WHERE sn_from.user_id = p_user_id
    AND sm.delivered_at IS NULL
    AND sm.to_selflet_id IS NULL  -- Addressed to future self (any)
  ORDER BY sn_from.created_at DESC;
END;
$$;


--
-- Name: get_relevant_breakthrough_patterns("text", "text", "text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."get_relevant_breakthrough_patterns"("p_phase" "text", "p_element" "text", "p_archetype" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 5) RETURNS TABLE("id" "uuid", "catalyst_type" "text", "transformation_type" "text", "emotional_shift" "text", "practice_offered" "text", "resonance_strength" numeric, "relevance_score" integer)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  direct_count integer;
BEGIN
  -- First try: exact phase + element match
  RETURN QUERY
  SELECT
    cb.id,
    cb.catalyst_type,
    cb.transformation_type,
    cb.emotional_shift,
    cb.practice_offered,
    cb.resonance_strength,
    (
      CASE WHEN cb.spiralogic_phase = p_phase THEN 3 ELSE 0 END +
      CASE WHEN cb.dominant_element = p_element THEN 2 ELSE 0 END +
      CASE WHEN p_archetype IS NOT NULL AND (cb.archetype_from = p_archetype OR cb.archetype_to = p_archetype) THEN 3 ELSE 0 END +
      CASE WHEN cb.created_at >= NOW() - INTERVAL '7 days' THEN 2 ELSE 0 END
    )::INTEGER as relevance_score
  FROM collective_breakthroughs cb
  WHERE cb.created_at >= NOW() - INTERVAL '30 days'
    AND (cb.spiralogic_phase = p_phase OR cb.dominant_element = p_element)
  ORDER BY relevance_score DESC, cb.created_at DESC
  LIMIT p_limit;

  -- Check if we found any matches
  GET DIAGNOSTICS direct_count = ROW_COUNT;

  -- Fallback: if no matches, return most recent patterns regardless of phase/element
  -- Label them with lower relevance score (adjacent resonance)
  IF direct_count = 0 THEN
    RETURN QUERY
    SELECT
      cb.id,
      cb.catalyst_type,
      cb.transformation_type,
      cb.emotional_shift,
      cb.practice_offered,
      cb.resonance_strength,
      1::INTEGER as relevance_score  -- Low score = adjacent resonance
    FROM collective_breakthroughs cb
    WHERE cb.created_at >= NOW() - INTERVAL '30 days'
    ORDER BY cb.created_at DESC
    LIMIT p_limit;
  END IF;
END;
$$;


