CREATE FUNCTION "public"."is_colleague"("practitioner_a" "uuid", "practitioner_b" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM practitioner_connections
    WHERE status = 'accepted'
