$$;


--
-- Name: log_maia_conversation_turn("text", integer, "text", "text", "text", "text", integer, "text", "text"[], "text"[], smallint, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."log_maia_conversation_turn"("p_session_id" "text", "p_turn_index" integer, "p_user_text" "text", "p_maia_text" "text", "p_processing_profile" "text", "p_primary_engine" "text", "p_latency_ms" integer, "p_element" "text", "p_topic_tags" "text"[], "p_consciousness_layers" "text"[], "p_consciousness_depth" smallint, "p_used_claude_consult" boolean) RETURNS bigint
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_turn_id BIGINT;
BEGIN
  INSERT INTO maia_turns (
    session_id,
    turn_index,
    user_text,
    maia_text,
    processing_profile,
    primary_engine,
    latency_ms,
    element,
    topic_tags,
    consciousness_layers_activated,
    consciousness_depth_achieved,
    used_claude_consult
  ) VALUES (
    p_session_id,
    p_turn_index,
    p_user_text,
    p_maia_text,
    p_processing_profile,
    COALESCE(p_primary_engine, 'deepseek-r1:latest'),
    p_latency_ms,
    p_element,
    COALESCE(p_topic_tags, '{}'),
    COALESCE(p_consciousness_layers, '{}'),
    p_consciousness_depth,
    COALESCE(p_used_claude_consult, FALSE)
  )
  ON CONFLICT (session_id, turn_index) DO UPDATE SET
    user_text = EXCLUDED.user_text,
    maia_text = EXCLUDED.maia_text,
    processing_profile = EXCLUDED.processing_profile,
    primary_engine = EXCLUDED.primary_engine,
    latency_ms = EXCLUDED.latency_ms,
    element = EXCLUDED.element,
    topic_tags = EXCLUDED.topic_tags,
    consciousness_layers_activated = EXCLUDED.consciousness_layers_activated,
    consciousness_depth_achieved = EXCLUDED.consciousness_depth_achieved,
    used_claude_consult = EXCLUDED.used_claude_consult
  RETURNING id INTO v_turn_id;

  RETURN v_turn_id;
END;
$$;


