--
-- Name: persist_deliberation("text", bigint, "text", "text", double precision, "text", "jsonb", integer, "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."persist_deliberation"("p_session_id" "text", "p_turn_id" bigint, "p_committee" "text", "p_final_classification" "text", "p_final_confidence" double precision, "p_decided_by" "text", "p_votes_json" "jsonb", "p_deliberation_ms" integer, "p_notes" "text", "p_meta_json" "jsonb" DEFAULT NULL::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_deliberation_id UUID;
BEGIN
  INSERT INTO deliberations (
    session_id,
    turn_id,
    committee,
    final_classification,
    final_confidence,
    decided_by,
    votes_json,
    deliberation_ms,
    notes,
    meta_json
  ) VALUES (
    p_session_id,
    p_turn_id,
    COALESCE(p_committee, 'mythic_atlas'),
    p_final_classification,
    p_final_confidence,
    COALESCE(p_decided_by, 'committee'),
    p_votes_json,
    p_deliberation_ms,
    p_notes,
    p_meta_json
  )
  RETURNING id INTO v_deliberation_id;

  -- Link the turn to this deliberation if turn_id provided
  IF p_turn_id IS NOT NULL THEN
    UPDATE maia_turns
    SET deliberation_id = v_deliberation_id
    WHERE id = p_turn_id;
  END IF;

  RETURN v_deliberation_id;
END;
$$;


