--
-- Name: practice_fields_clear_identity_ratification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."practice_fields_clear_identity_ratification"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF (NEW.about_practice IS DISTINCT FROM OLD.about_practice)
     OR (NEW.how_we_work_together IS DISTINCT FROM OLD.how_we_work_together) THEN
    -- Only clear when the caller did not ratify in this same statement.
    IF NEW.identity_ratified_at IS NOT DISTINCT FROM OLD.identity_ratified_at THEN
      NEW.identity_ratified_at := NULL;
      NEW.identity_ratified_by := NULL;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: practitioner_client_link_is_permanent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."practitioner_client_link_is_permanent"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF OLD.member_id IS NOT NULL AND NEW.member_id IS DISTINCT FROM OLD.member_id THEN
    RAISE EXCEPTION
      'practitioner_clients.member_id is write-once (relationship %): a linked relationship '
      'cannot be re-pointed at another member, and cannot be unlinked. End this relationship '
      'and create a new one.', OLD.id;
  END IF;
  IF NEW.member_id IS NOT NULL AND OLD.member_id IS NULL AND NEW.linked_at IS NULL THEN
    NEW.linked_at := NOW();
  END IF;
  NEW.updated_at := NOW();
  RETURN NEW;
END;
$$;


--
-- Name: practitioner_client_reconcile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."practitioner_client_reconcile"() RETURNS TABLE("queued" bigint, "auto_linked" bigint)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  n_queued BIGINT := 0;
  n_linked BIGINT := 0;
BEGIN

INSERT INTO practitioner_client_reconciliation
  (relationship_id, candidate_member_id, match_basis, auto_linkable, provenance, ambiguity_reason)
SELECT
  pc.id,
  ev.candidate_member_id,
  ev.match_basis,
  ev.match_basis IN ('verified_invitation', 'verified_unique_email'),
  jsonb_build_object(
    'verified_email_matches', ev.verified_email_matches,
    'any_email_matches',      ev.any_email_matches,
    'claimed_invitations',    ev.claimed_invitations,
    'competing_relationships', ev.competing_relationships,
    'normalized_email',       pc.normalized_invitation_email
  ),
  ev.ambiguity_reason
FROM practitioner_clients pc
CROSS JOIN LATERAL (
  WITH invite AS (
    SELECT ci.claimed_by_member_id AS member_id, count(*) OVER () AS n
    FROM client_invites ci
    WHERE ci.client_id = pc.id
      AND ci.claimed_at IS NOT NULL
      AND ci.claimed_by_member_id IS NOT NULL
  ),
  verified AS (
    SELECT m.id AS member_id, count(*) OVER () AS n
    FROM members m
    WHERE pc.normalized_invitation_email IS NOT NULL
      AND lower(btrim(m.email)) = pc.normalized_invitation_email
      AND m.email_verified IS TRUE
  ),
  anymatch AS (
    SELECT count(*) AS n
    FROM members m
    WHERE pc.normalized_invitation_email IS NOT NULL
      AND lower(btrim(m.email)) = pc.normalized_invitation_email
  ),
  competing AS (
    SELECT count(*) AS n
    FROM practitioner_clients other
    WHERE other.id <> pc.id
      AND other.practitioner_id = pc.practitioner_id
      AND other.normalized_invitation_email IS NOT NULL
      AND other.normalized_invitation_email = pc.normalized_invitation_email
      AND other.relationship_status <> 'ended'
  )
  SELECT
    (SELECT count(DISTINCT member_id) FROM invite)                       AS claimed_invitations,
    (SELECT coalesce(max(n), 0) FROM verified)                           AS verified_email_matches,
    (SELECT n FROM anymatch)                                             AS any_email_matches,
    (SELECT n FROM competing)                                            AS competing_relationships,
    CASE
      WHEN (SELECT count(DISTINCT member_id) FROM invite) = 1
        THEN (SELECT DISTINCT member_id FROM invite)
      WHEN (SELECT count(DISTINCT member_id) FROM invite) = 0
       AND (SELECT coalesce(max(n), 0) FROM verified) = 1
       AND (SELECT n FROM competing) = 0
        THEN (SELECT member_id FROM verified LIMIT 1)
      ELSE NULL
    END                                                                   AS candidate_member_id,
    CASE
      WHEN (SELECT count(DISTINCT member_id) FROM invite) > 1  THEN 'conflicting_invitation'
      WHEN (SELECT count(DISTINCT member_id) FROM invite) = 1  THEN 'verified_invitation'
      WHEN pc.normalized_invitation_email IS NULL              THEN 'missing_email'
      WHEN (SELECT n FROM anymatch) = 0                        THEN 'missing_member'
      WHEN (SELECT n FROM competing) > 0                       THEN 'ambiguous_multiple_relationships'
      WHEN (SELECT coalesce(max(n), 0) FROM verified) = 1      THEN 'verified_unique_email'
      WHEN (SELECT n FROM anymatch) > 1                        THEN 'ambiguous_multiple_members'
      ELSE 'manual_review_required'
    END                                                                   AS match_basis,
    CASE
      WHEN (SELECT count(DISTINCT member_id) FROM invite) > 1
        THEN 'More than one member claimed an invitation issued from this relationship.'
      WHEN (SELECT n FROM competing) > 0
        THEN 'Another live relationship for this practitioner carries the same invitation email.'
      WHEN (SELECT n FROM anymatch) > 1
        THEN 'The invitation email matches more than one member account.'
      WHEN (SELECT n FROM anymatch) = 1 AND (SELECT coalesce(max(n), 0) FROM verified) = 0
        THEN 'The only matching member has not verified that email address.'
      ELSE NULL
    END                                                                   AS ambiguity_reason
) ev
WHERE pc.member_id IS NULL
  AND NOT EXISTS (
    SELECT 1 FROM practitioner_client_reconciliation r
    WHERE r.relationship_id = pc.id AND r.reconciliation_status = 'open'
  );

GET DIAGNOSTICS n_queued = ROW_COUNT;

-- 5b. Auto-link ONLY the two admissible bases. Everything else waits for a human.
-- Email similarity, display-name similarity and practitioner expectation are not
-- evidence. A wrong link exposes one person's developmental record to another.
UPDATE practitioner_clients pc
   SET member_id = r.candidate_member_id,
       linked_at = NOW()
  FROM practitioner_client_reconciliation r
 WHERE r.relationship_id = pc.id
   AND r.reconciliation_status = 'open'
   AND r.auto_linkable IS TRUE
   AND r.candidate_member_id IS NOT NULL
   AND pc.member_id IS NULL;

GET DIAGNOSTICS n_linked = ROW_COUNT;

UPDATE practitioner_client_reconciliation r
   SET reconciliation_status = 'auto_linked',
       resolved_at = NOW()
  FROM practitioner_clients pc
 WHERE r.relationship_id = pc.id
   AND r.reconciliation_status = 'open'
   AND r.auto_linkable IS TRUE
   AND pc.member_id IS NOT NULL
   AND pc.member_id = r.candidate_member_id;

queued := n_queued;
auto_linked := n_linked;
RETURN NEXT;
END;
$$;


--
-- Name: prevent_edit_after_send(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prevent_edit_after_send"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Only apply to referrals that have been sent (not draft)
  IF OLD.status <> 'draft' THEN

    -- NEVER allow routing changes after send
    IF NEW.connection_id IS DISTINCT FROM OLD.connection_id
       OR NEW.from_practitioner_id IS DISTINCT FROM OLD.from_practitioner_id
       OR NEW.to_practitioner_id IS DISTINCT FROM OLD.to_practitioner_id
    THEN
      RAISE EXCEPTION 'Cannot modify referral routing after sending';
    END IF;

    -- NEVER allow content field changes after send
    -- (requester_note is private scratchpad - allowed to change)
    IF NEW.client_age_range IS DISTINCT FROM OLD.client_age_range
       OR NEW.client_pronouns IS DISTINCT FROM OLD.client_pronouns
       OR NEW.presenting_themes IS DISTINCT FROM OLD.presenting_themes
       OR NEW.urgency IS DISTINCT FROM OLD.urgency
       OR NEW.constraints IS DISTINCT FROM OLD.constraints
    THEN
      RAISE EXCEPTION 'Cannot modify referral content after sending';
    END IF;

    -- Note: These are ALLOWED after send:
    -- - status (for transitions: sent -> received -> accepted/declined -> closed)
    -- - timestamps (sent_at, viewed_at, responded_at)
    -- - requester_note (private to requester, can update their own notes)
    -- - recipient_note (private to recipient, can update their own notes)
    -- - consent fields (controlled by sanitize_consent_state trigger)
    -- - sealed_at, sealed_reason (controlled by seal trigger)

  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: prune_email_delivery_ledger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."prune_email_delivery_ledger"() RETURNS TABLE("rolled_up" bigint, "deleted" bigint)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_rolled bigint := 0;
  v_deleted bigint := 0;
BEGIN
  WITH due AS (
    SELECT date_trunc('month', created_at)::date AS month,
           purpose, lane, provider, state, count(*) AS n
      FROM public.email_delivery_attempts
     WHERE created_at < NOW() - INTERVAL '90 days'
     GROUP BY 1,2,3,4,5
  ), upserted AS (
    INSERT INTO public.email_delivery_monthly AS m
                (month, purpose, lane, provider, state, attempts)
    SELECT month, purpose, lane, provider, state, n FROM due
    ON CONFLICT (month, purpose, lane, provider, state)
      DO UPDATE SET attempts = m.attempts + EXCLUDED.attempts
    RETURNING 1
  )
  SELECT count(*) INTO v_rolled FROM upserted;

  WITH gone AS (
    DELETE FROM public.email_delivery_attempts
     WHERE created_at < NOW() - INTERVAL '90 days'
    RETURNING 1
  )
  SELECT count(*) INTO v_deleted FROM gone;

  DELETE FROM public.email_delivery_monthly
   WHERE month < (date_trunc('month', NOW()) - INTERVAL '13 months')::date;

  RETURN QUERY SELECT v_rolled, v_deleted;
END;
$$;


--
-- Name: purge_archived_room_events(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."purge_archived_room_events"("p_older_than_days" integer DEFAULT 30) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_count INTEGER;
BEGIN
  DELETE FROM commons_room_events
  WHERE retention_status IN ('archived', 'expired')
    AND updated_at < now() - (p_older_than_days || ' days')::INTERVAL;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: refuse_material_relationship_conflict(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."refuse_material_relationship_conflict"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  counterpart INTEGER;
BEGIN
  -- FIRST, and identically in both branches: whichever table fired, the same
  -- pair yields the same two keys, so a consideration and a declaration for
  -- one material contend for one lock.
  PERFORM pg_advisory_xact_lock(
    hashtext(NEW.living_work_id::text),
    hashtext(NEW.material_type || ':' || NEW.material_id)
  );

  IF TG_TABLE_NAME = 'living_work_material_considerations' THEN
    SELECT count(*) INTO counterpart
      FROM living_work_materials
     WHERE living_work_id = NEW.living_work_id
       AND material_type  = NEW.material_type
       AND material_id    = NEW.material_id;
    IF counterpart > 0 THEN
      RAISE EXCEPTION
        'material_relationship_conflict: this material already belongs to that '
        'work. Withdraw the belonging in the same transaction before recording '
        'a consideration.'
        USING ERRCODE = 'restrict_violation';
    END IF;
  ELSE
    SELECT count(*) INTO counterpart
      FROM living_work_material_considerations
     WHERE living_work_id = NEW.living_work_id
       AND material_type  = NEW.material_type
       AND material_id    = NEW.material_id;
    IF counterpart > 0 THEN
      RAISE EXCEPTION
        'material_relationship_conflict: this material is under consideration '
        'for that work. Remove the consideration in the same transaction '
        'before declaring belonging.'
        USING ERRCODE = 'restrict_violation';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: reset_failed_analysis_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."reset_failed_analysis_jobs"("max_attempts" integer DEFAULT 3) RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_count INT;
BEGIN
  UPDATE comms_analysis_queue
  SET status = 'queued',
      started_at = NULL,
      finished_at = NULL
  WHERE status = 'failed'
    AND attempts < max_attempts;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


