END;
$$;


--
-- Name: s5_refuse_tombstoned(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."s5_refuse_tombstoned"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  row_id TEXT;
  row_session TEXT;
  row_created TIMESTAMPTZ;
  hit_manifest UUID;
BEGIN
  -- to_jsonb(NEW) keeps the function valid across lanes regardless of exact
  -- column sets (a missing key yields NULL rather than a runtime error).
  row_id := to_jsonb(NEW) ->> 'id';
  row_session := to_jsonb(NEW) ->> 'session_id';
  row_created := (to_jsonb(NEW) ->> 'created_at')::timestamptz;

  -- Refusal evidence is content-free but COMPLETE: manifest id, table, reason,
  -- row-id prefix, txid, timestamp — a refused resurrection must be
  -- distinguishable from a successful write in the postgres log alone.
  -- Tables are schema-qualified: restore sessions run with an EMPTY
  -- search_path (pg_dump emits set_config('search_path','',false)), and this
  -- trigger must work exactly there (found by the merge-gate rehearsal).
  SELECT manifest_id INTO hit_manifest FROM public.provenance_tombstones
    WHERE object_kind = TG_TABLE_NAME AND object_id = row_id LIMIT 1;
  IF hit_manifest IS NOT NULL THEN
    RAISE WARNING '[PROVENANCE] restore refused — reason=tombstone table=% id_prefix=% manifest=% txid=% at=%',
      TG_TABLE_NAME, left(row_id, 12), hit_manifest, txid_current(), clock_timestamp();
    RETURN NULL;  -- idempotent suppression is intentional here ONLY (restore path);
                  -- ordinary unattested writes hard-fail via the mint gates below
  END IF;

  SELECT s.manifest_id INTO hit_manifest FROM public.deletion_manifest_scopes s
    WHERE s.table_name = TG_TABLE_NAME
      AND (s.session_id IS NULL OR s.session_id = row_session)
      AND (s.window_start IS NULL OR row_created >= s.window_start)
      AND (s.window_end IS NULL OR row_created <= s.window_end)
      -- a scope with only NULLs cannot exist (table CHECK), so this cannot
      -- swallow unscoped rows
      AND (s.session_id IS NOT NULL OR s.window_start IS NOT NULL)
    LIMIT 1;
  IF hit_manifest IS NOT NULL THEN
    RAISE WARNING '[PROVENANCE] restore refused — reason=manifest-scope table=% id_prefix=% manifest=% txid=% at=%',
      TG_TABLE_NAME, left(row_id, 12), hit_manifest, txid_current(), clock_timestamp();
    RETURN NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: s5_refuse_unknown_collective(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."s5_refuse_unknown_collective"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.posture_at_creation = 'unknown-historical'
     AND NEW.crossing_allowed = TRUE
     AND (TG_OP = 'INSERT' OR OLD.crossing_allowed IS DISTINCT FROM NEW.crossing_allowed) THEN
    RAISE EXCEPTION '[PROVENANCE] refused — unknown-historical atom may not become collective-eligible (id=%)',
      left(NEW.id::text, 12);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: s5_require_atom_attestation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."s5_require_atom_attestation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Governed-restore lane: replay of historical atoms, same rule as turns.
  IF NEW.posture_at_creation = 'unknown-historical'
     AND NEW.generated_by = 'unattributed-historical'
     AND current_setting('s5.restore_lane', true) = 'governed' THEN
    RETURN NEW;
  END IF;
  IF NEW.posture_at_creation IS DISTINCT FROM 'normal' THEN
    RAISE EXCEPTION '[PROVENANCE] mint failed — member_memory_atoms INSERT refused: posture % is not writable',
      COALESCE(NEW.posture_at_creation, 'NULL');
  END IF;
  IF NEW.generated_by IS NULL OR NEW.generated_by = 'unattributed-historical' THEN
    RAISE EXCEPTION '[PROVENANCE] mint failed — member_memory_atoms INSERT refused: generated_by % is not mintable',
      COALESCE(NEW.generated_by, 'NULL');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: s5_require_minted_provenance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."s5_require_minted_provenance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- Governed-restore lane: a restore REPLAYS rows, it does not mint them.
  -- Historical (unknown-historical) rows may re-enter ONLY when the session
  -- has declared the governed restore lane (set by scripts/restore-governed.sh;
  -- tombstone/scope filtering still applies via s5_refuse_tombstoned).
  -- Consequence, deliberate: an UNGOVERNED restore of any dump containing
  -- historical rows fails loudly at the first such row — the governed path is
  -- structurally unavoidable for historical dumps, not merely procedural.
  IF NEW.posture_at_creation = 'unknown-historical'
     AND current_setting('s5.restore_lane', true) = 'governed' THEN
    RETURN NEW;
  END IF;
  IF NEW.posture_at_creation IS DISTINCT FROM 'normal' THEN
    RAISE EXCEPTION '[PROVENANCE] mint failed — % INSERT refused: posture % is not writable (sanctuary never persists; unknown-historical is never minted anew outside the governed restore lane)',
      TG_TABLE_NAME, COALESCE(NEW.posture_at_creation, 'NULL');
  END IF;
  IF NEW.provenance IS NULL
     OR NOT (NEW.provenance ? 'createdBy')
     OR NOT (NEW.provenance ? 'generatedBy')
     OR NOT (NEW.provenance ? 'postureAtCreation')
     OR NOT (NEW.provenance ? 'sourceContainer')
     OR NOT (NEW.provenance ? 'source')
     OR NOT (NEW.provenance ? 'persistencePolicy') THEN
    RAISE EXCEPTION '[PROVENANCE] mint failed — % INSERT refused: provenance missing or incomplete',
      TG_TABLE_NAME;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sanitize_consent_state(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sanitize_consent_state"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- PHYSICS RULE: If name is not shared, identity MUST NOT exist
  -- This closes the "consent true but not shared, name stored anyway" leak
  IF NEW.client_name_shared = false OR NEW.client_name_shared IS NULL THEN
    NEW.client_name := NULL;
    NEW.client_contact := NULL;
  END IF;

  -- PHYSICS RULE: name_shared requires consent_given
  IF NEW.client_name_shared = true AND (NEW.client_consent_given = false OR NEW.client_consent_given IS NULL) THEN
    NEW.client_name_shared := false;
    NEW.client_name := NULL;
    NEW.client_contact := NULL;
  END IF;

  -- If consent is being revoked, clear everything
  IF TG_OP = 'UPDATE' AND OLD.client_consent_given = true AND NEW.client_consent_given = false THEN
    NEW.client_name_shared := false;
    NEW.consent_recorded_at := NULL;
    -- client_name and client_contact already NULLed above
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: seal_referrals_on_connection_break(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."seal_referrals_on_connection_break"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- UPDATE: If connection was accepted and is now anything else, seal referrals
  IF TG_OP = 'UPDATE'
     AND OLD.status = 'accepted'
     AND NEW.status IS DISTINCT FROM 'accepted'
  THEN
    UPDATE referral_requests
    SET
      sealed_at = NOW(),
      sealed_reason = 'connection_' || NEW.status,
      -- Redact identity even if it was shared
      client_name = NULL,
      client_contact = NULL,
      client_name_shared = false,
      client_consent_given = false
    WHERE connection_id = NEW.id
      AND sealed_at IS NULL;
  END IF;

  -- DELETE: Seal all referrals for this connection
  IF TG_OP = 'DELETE' THEN
    UPDATE referral_requests
    SET
      sealed_at = NOW(),
      sealed_reason = 'connection_deleted',
      client_name = NULL,
      client_contact = NULL,
      client_name_shared = false,
      client_consent_given = false
    WHERE connection_id = OLD.id
      AND sealed_at IS NULL;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


