--
-- Name: sms_status_rank("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."sms_status_rank"("s" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE s
    WHEN 'accepted'    THEN 1
    WHEN 'scheduled'   THEN 1
    WHEN 'queued'      THEN 2
    WHEN 'sending'     THEN 3
    WHEN 'sent'        THEN 4
    WHEN 'delivered'   THEN 5
    WHEN 'undelivered' THEN 5
    WHEN 'failed'      THEN 5
    ELSE 0
  END
$$;


