-- Name: update_channel_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."update_channel_stats"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE community_channels
    SET post_count = post_count + 1,
        last_activity_at = NOW()
    WHERE id = NEW.channel_id;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE community_channels
    SET post_count = post_count - 1
    WHERE id = OLD.channel_id;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


