    LANGUAGE "plpgsql"
    AS $$
BEGIN
  UPDATE hypothesis_test_runs
  SET
    sample_size = sample_size + 1,
    metric_sum = metric_sum + p_metric_value,
    metric_count = metric_count + 1
  WHERE hypothesis_id = p_hypothesis_id
    AND test_group = p_test_group
    AND is_active = TRUE;
END;
$$;


