--

CREATE FUNCTION "public"."weekly_weight"("member_uuid" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE
    AS $$
  SELECT COALESCE(SUM(weight), 0)::INTEGER
  FROM focus_weight_log
  WHERE member_id = member_uuid
    AND created_at > NOW() - INTERVAL '7 days';
$$;


--
-- Name: wisdom_fields_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."wisdom_fields_set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;


--
-- Name: working_draft_revisions_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION "public"."working_draft_revisions_immutable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RAISE EXCEPTION 'working_draft_revisions is append-only: % is not permitted', TG_OP;
END;
$$;


