--
-- Name: agent_accuracy; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."agent_accuracy" AS
 SELECT "v"."member",
    "count"(*) AS "total_votes",
    "avg"("v"."confidence") AS "avg_confidence",
    "sum"(
        CASE
            WHEN ("v"."label" = "d"."final_label") THEN 1
            ELSE 0
        END) AS "voted_with_consensus",
    "sum"(
        CASE
            WHEN (("f"."corrected_label" IS NOT NULL) AND ("v"."label" = "f"."corrected_label")) THEN 1
            ELSE 0
        END) AS "correct_when_corrected",
    "sum"(
        CASE
            WHEN ("f"."corrected_label" IS NOT NULL) THEN 1
            ELSE 0
        END) AS "total_corrections"
   FROM (("public"."maia_decision_votes" "v"
     JOIN "public"."maia_decisions" "d" ON (("d"."id" = "v"."decision_id")))
     LEFT JOIN "public"."maia_decision_feedback" "f" ON (("f"."decision_id" = "d"."id")))
  GROUP BY "v"."member";


