    CONSTRAINT "maia_turn_feedback_felt_seen_score_check" CHECK ((("felt_seen_score" IS NULL) OR (("felt_seen_score" >= 1) AND ("felt_seen_score" <= 5)))),
    CONSTRAINT "maia_turn_feedback_safety_score_check" CHECK ((("safety_score" IS NULL) OR (("safety_score" >= 1) AND ("safety_score" <= 5)))),
