--
-- Name: agent_vote_outcomes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."agent_vote_outcomes" AS
 SELECT ("v"."value" ->> 'member'::"text") AS "agent",
    ("v"."value" ->> 'classification'::"text") AS "agent_vote",
    (("v"."value" ->> 'confidence'::"text"))::double precision AS "agent_confidence",
    ("v"."value" ->> 'rationale'::"text") AS "agent_rationale",
    "d"."final_classification",
    "d"."final_confidence",
    "f"."attunement_score",
    "f"."felt_seen_score",
    "f"."rupture_mark",
    (("v"."value" ->> 'classification'::"text") = "d"."final_classification") AS "voted_with_consensus",
        CASE
            WHEN ((COALESCE(("f"."attunement_score")::integer, 0) >= 4) AND (COALESCE("f"."rupture_mark", false) = false)) THEN true
            ELSE false
        END AS "positive_outcome",
    "d"."created_at"
   FROM (("public"."deliberations" "d"
     CROSS JOIN LATERAL "jsonb_array_elements"("d"."votes_json") "v"("value"))
     LEFT JOIN "public"."maia_turn_feedback" "f" ON ((("f"."deliberation_id" = "d"."id") OR ("f"."turn_id" = "d"."turn_id"))))
  WHERE ("f"."id" IS NOT NULL);


