);


--
-- Name: ain_shape_telemetry_turn_join; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."ain_shape_telemetry_turn_join" AS
 WITH "ranked" AS (
         SELECT "ast"."id" AS "telemetry_id",
            "ast"."session_id",
            "ast"."formed_at",
            "ast"."route",
            "ast"."model",
            "ast"."pass",
            "ast"."score",
            "ast"."mirror",
            "ast"."bridge",
            "ast"."permission",
            "ast"."next_step",
            "mt"."id" AS "turn_id",
            "mt"."turn_index",
            "mt"."created_at" AS "turn_created_at",
            "abs"(EXTRACT(epoch FROM ("mt"."created_at" - "ast"."formed_at"))) AS "time_diff_seconds",
            "row_number"() OVER (PARTITION BY "ast"."id" ORDER BY ("abs"(EXTRACT(epoch FROM ("mt"."created_at" - "ast"."formed_at"))))) AS "rn"
           FROM ("public"."ain_shape_telemetry" "ast"
             JOIN "public"."maia_turns" "mt" ON ((("mt"."session_id" = "ast"."session_id") AND (("mt"."created_at" >= ("ast"."formed_at" - '00:10:00'::interval)) AND ("mt"."created_at" <= ("ast"."formed_at" + '00:10:00'::interval))))))
        )
 SELECT "telemetry_id",
    "session_id",
    "formed_at",
    "route",
    "model",
    "pass",
    "score",
    "mirror",
    "bridge",
    "permission",
    "next_step",
    "turn_id",
    "turn_index",
    "turn_created_at",
    "time_diff_seconds"
   FROM "ranked"
  WHERE ("rn" = 1);


--
-- Name: ain_shape_telemetry_turn_decision_join; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."ain_shape_telemetry_turn_decision_join" AS
 SELECT "j"."telemetry_id",
    "j"."session_id",
    "j"."formed_at",
    "j"."route",
    "j"."model",
    "j"."pass",
    "j"."score",
    "j"."mirror",
    "j"."bridge",
    "j"."permission",
    "j"."next_step",
    "j"."turn_id",
    "j"."turn_index",
    "j"."turn_created_at",
    "j"."time_diff_seconds",
    "d"."id" AS "decision_id",
    "d"."final_label",
    "d"."decided_by",
    "d"."deliberation_triggered"
   FROM ("public"."ain_shape_telemetry_turn_join" "j"
     LEFT JOIN "public"."maia_decisions" "d" ON (("d"."turn_id" = "j"."turn_id")));


