);


--
-- Name: ain_expansion_score; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."ain_expansion_score" AS
 WITH "base" AS (
         SELECT "jd"."telemetry_id",
            "jd"."session_id",
            "jd"."turn_id",
            "jd"."turn_index",
            COALESCE("jd"."turn_created_at", "jd"."formed_at") AS "ts",
            (COALESCE(("jd"."score")::integer, 0))::double precision AS "shape_score",
            COALESCE("jd"."mirror", false) AS "mirror",
            COALESCE("jd"."bridge", false) AS "bridge",
            COALESCE("jd"."permission", false) AS "permission",
            COALESCE("jd"."next_step", false) AS "next_step",
            COALESCE("jd"."deliberation_triggered", false) AS "deliberation_triggered"
           FROM "public"."ain_shape_telemetry_turn_decision_join" "jd"
        ), "mem" AS (
         SELECT "conversation_memory_uses"."session_id",
            "conversation_memory_uses"."message_id",
            "count"(*) AS "memory_uses",
            ("avg"(COALESCE("conversation_memory_uses"."confidence_score", (0)::numeric)))::double precision AS "memory_confidence"
           FROM "public"."conversation_memory_uses"
          GROUP BY "conversation_memory_uses"."session_id", "conversation_memory_uses"."message_id"
        ), "joined" AS (
         SELECT "b"."telemetry_id",
            "b"."session_id",
            "b"."turn_id",
            "b"."turn_index",
            "b"."ts",
            "b"."shape_score",
            "b"."mirror",
            "b"."bridge",
            "b"."permission",
            "b"."next_step",
            "b"."deliberation_triggered",
            (COALESCE("m"."memory_uses", (0)::bigint))::double precision AS "memory_uses",
            COALESCE("m"."memory_confidence", (0)::double precision) AS "memory_confidence"
           FROM ("base" "b"
             LEFT JOIN "mem" "m" ON ((("m"."session_id" = "b"."session_id") AND ("m"."message_id" = ("b"."turn_id")::"text"))))
        ), "components" AS (
         SELECT "joined"."telemetry_id",
            "joined"."session_id",
            "joined"."turn_id",
            "joined"."turn_index",
            "joined"."ts",
            "joined"."shape_score",
            "joined"."mirror",
            "joined"."bridge",
            "joined"."permission",
            "joined"."next_step",
            "joined"."deliberation_triggered",
            "joined"."memory_uses",
            "joined"."memory_confidence",
            LEAST((1.0)::double precision, GREATEST((0.0)::double precision, ((((("joined"."shape_score" / (4.0)::double precision) + (
                CASE
                    WHEN "joined"."mirror" THEN 0.10
                    ELSE (0)::numeric
                END)::double precision) + (
                CASE
                    WHEN "joined"."bridge" THEN 0.10
                    ELSE (0)::numeric
                END)::double precision) + (
                CASE
                    WHEN "joined"."permission" THEN 0.10
                    ELSE (0)::numeric
                END)::double precision) + (
                CASE
                    WHEN "joined"."next_step" THEN 0.10
                    ELSE (0)::numeric
                END)::double precision))) AS "shape_component",
            LEAST((1.0)::double precision, GREATEST((0.0)::double precision, ((LEAST((5.0)::double precision, "joined"."memory_uses") / (5.0)::double precision) * "joined"."memory_confidence"))) AS "memory_component",
                CASE
                    WHEN "joined"."deliberation_triggered" THEN 1.0
                    ELSE 0.0
                END AS "deliberation_component"
           FROM "joined"
        )
 SELECT "telemetry_id",
    "session_id",
    "turn_id",
    "turn_index",
    "ts",
    "shape_score",
    "mirror",
    "bridge",
    "permission",
    "next_step",
    "deliberation_triggered",
    "memory_uses",
    "memory_confidence",
    "shape_component",
    "memory_component",
    "deliberation_component",
    LEAST((1.0)::double precision, GREATEST((0.0)::double precision, ((((0.70)::double precision * "shape_component") + ((0.25)::double precision * "memory_component")) + ((0.05 * "deliberation_component"))::double precision))) AS "expansion_score"
   FROM "components";


--
-- Name: ain_expansion_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."ain_expansion_daily" AS
 SELECT ("date_trunc"('day'::"text", "ts"))::"date" AS "day",
    "count"(*) AS "n",
    "avg"("expansion_score") AS "avg_expansion_score",
    "avg"("shape_component") AS "avg_shape_component",
    "avg"("memory_component") AS "avg_memory_component",
    "avg"("deliberation_component") AS "avg_deliberation_component",
    "avg"(
        CASE
            WHEN "permission" THEN 1
            ELSE 0
        END) AS "permission_rate",
    "avg"(
        CASE
            WHEN "bridge" THEN 1
            ELSE 0
        END) AS "bridge_rate",
    "avg"(
        CASE
            WHEN "next_step" THEN 1
            ELSE 0
        END) AS "next_step_rate",
    "avg"(
        CASE
            WHEN "mirror" THEN 1
            ELSE 0
        END) AS "mirror_rate",
    "avg"(
        CASE
            WHEN ("memory_uses" > (0)::double precision) THEN 1
            ELSE 0
        END) AS "memory_use_rate",
    "avg"("memory_confidence") AS "avg_memory_confidence"
   FROM "public"."ain_expansion_score"
  GROUP BY (("date_trunc"('day'::"text", "ts"))::"date")
  ORDER BY (("date_trunc"('day'::"text", "ts"))::"date") DESC;


