-- Name: ain_memory_by_session; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."ain_memory_by_session" AS
 SELECT "session_id",
    "count"(*) AS "memory_uses",
    "count"(DISTINCT "user_id") AS "users_in_memory_stream",
    "count"(DISTINCT (("memory_table" || ':'::"text") || "memory_id")) AS "unique_memories_used",
    "avg"(COALESCE("confidence_score", (0)::numeric)) AS "avg_confidence_score",
    "avg"(COALESCE("retrieval_score", (0)::numeric)) AS "avg_retrieval_score",
    "avg"(COALESCE("semantic_score", (0)::numeric)) AS "avg_semantic_score",
    "avg"(COALESCE("recency_score", (0)::numeric)) AS "avg_recency_score",
    "min"("created_at") AS "first_memory_use_at",
    "max"("created_at") AS "last_memory_use_at"
   FROM "public"."conversation_memory_uses"
  GROUP BY "session_id";


--
-- Name: ain_memory_by_turn; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."ain_memory_by_turn" AS
 WITH "ranked" AS (
         SELECT "cmu"."id" AS "memory_use_id",
            "cmu"."session_id",
            "cmu"."user_id",
            "cmu"."created_at" AS "memory_created_at",
            "cmu"."memory_table",
            "cmu"."memory_id",
            "cmu"."used_as",
            "cmu"."retrieval_score",
            "cmu"."semantic_score",
            "cmu"."recency_score",
            "cmu"."confidence_score",
            "mt"."id" AS "turn_id",
            "mt"."turn_index",
            "mt"."created_at" AS "turn_created_at",
            "abs"(EXTRACT(epoch FROM ("mt"."created_at" - "cmu"."created_at"))) AS "time_diff_seconds",
            "row_number"() OVER (PARTITION BY "cmu"."id" ORDER BY ("abs"(EXTRACT(epoch FROM ("mt"."created_at" - "cmu"."created_at"))))) AS "rn"
           FROM ("public"."conversation_memory_uses" "cmu"
             JOIN "public"."maia_turns" "mt" ON ((("mt"."session_id" = "cmu"."session_id") AND (("mt"."created_at" >= ("cmu"."created_at" - '00:00:30'::interval)) AND ("mt"."created_at" <= ("cmu"."created_at" + '00:00:30'::interval))))))
        )
 SELECT "session_id",
    "turn_id",
    "turn_index",
    "min"("turn_created_at") AS "turn_created_at",
    "count"(*) AS "memory_uses",
    "count"(DISTINCT (("memory_table" || ':'::"text") || "memory_id")) AS "unique_memories_used",
    "avg"(COALESCE("confidence_score", (0)::numeric)) AS "avg_confidence_score",
    "avg"(COALESCE("retrieval_score", (0)::numeric)) AS "avg_retrieval_score",
    "avg"(COALESCE("semantic_score", (0)::numeric)) AS "avg_semantic_score",
    "avg"(COALESCE("recency_score", (0)::numeric)) AS "avg_recency_score",
    "avg"("time_diff_seconds") AS "avg_time_diff_seconds",
    "max"("time_diff_seconds") AS "max_time_diff_seconds"
   FROM "ranked"
  WHERE ("rn" = 1)
  GROUP BY "session_id", "turn_id", "turn_index"
  ORDER BY ("min"("turn_created_at")) DESC;


--
-- Name: ain_memory_by_user; Type: VIEW; Schema: public; Owner: -
