    "count"(DISTINCT (("memory_table" || ':'::"text") || "memory_id")) AS "unique_memories_used",
    "avg"(COALESCE("confidence_score", (0)::numeric)) AS "avg_confidence_score",
    "avg"(COALESCE("retrieval_score", (0)::numeric)) AS "avg_retrieval_score",
    "avg"(COALESCE("semantic_score", (0)::numeric)) AS "avg_semantic_score",
    "avg"(COALESCE("recency_score", (0)::numeric)) AS "avg_recency_score",
    "min"("created_at") AS "first_memory_use_at",
