--
-- Name: confidence_calibration; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."confidence_calibration" AS
 SELECT "d"."deliberation_triggered",
    "d"."trigger_reason",
        CASE
            WHEN ("d"."final_confidence" >= (0.8)::double precision) THEN 'high'::"text"
            WHEN ("d"."final_confidence" >= (0.5)::double precision) THEN 'medium'::"text"
            ELSE 'low'::"text"
        END AS "confidence_band",
    "count"(*) AS "total",
    "sum"(
        CASE
            WHEN ("f"."attunement_score" >= 4) THEN 1
            ELSE 0
        END) AS "positive_outcomes",
    "sum"(
        CASE
            WHEN ("f"."attunement_score" <= 2) THEN 1
            ELSE 0
        END) AS "negative_outcomes",
    "sum"(
        CASE
            WHEN ("f"."corrected_label" IS NOT NULL) THEN 1
            ELSE 0
        END) AS "corrections"
   FROM ("public"."maia_decisions" "d"
     LEFT JOIN "public"."maia_decision_feedback" "f" ON (("f"."decision_id" = "d"."id")))
  WHERE ("f"."attunement_score" IS NOT NULL)
  GROUP BY "d"."deliberation_triggered", "d"."trigger_reason",
        CASE
            WHEN ("d"."final_confidence" >= (0.8)::double precision) THEN 'high'::"text"
            WHEN ("d"."final_confidence" >= (0.5)::double precision) THEN 'medium'::"text"
            ELSE 'low'::"text"
        END;


