--
-- Name: decision_executor_pairs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."decision_executor_pairs" AS
 SELECT "d"."id" AS "decision_id",
    "d"."final_label",
    "d"."final_confidence",
    "d"."decided_by",
    "d"."created_at" AS "decision_created_at",
    "d"."deliberation_triggered",
    "e"."id" AS "executor_run_id",
    "e"."task_id",
    "e"."provider",
    "e"."task_type",
    "e"."risk",
    "e"."ok" AS "executor_ok",
    "e"."summary" AS "executor_summary",
    "e"."duration_ms",
    "e"."created_at" AS "executor_created_at"
   FROM ("public"."maia_decisions" "d"
     LEFT JOIN "public"."ain_executor_runs" "e" ON (("e"."deliberation_id" = ("d"."id")::"text")))
  ORDER BY "d"."created_at" DESC;


