    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "experience_type" "text" NOT NULL,
    "content" "text" NOT NULL,
    "element" "text",
    "tags" "text"[] DEFAULT '{}'::"text"[],
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "decision_experiences_element_check" CHECK (("element" = ANY (ARRAY['fire'::"text", 'water'::"text", 'earth'::"text", 'air'::"text", 'aether'::"text"]))),
    CONSTRAINT "decision_experiences_experience_type_check" CHECK (("experience_type" = ANY (ARRAY['field_event'::"text", 'reflection'::"text", 'breakthrough'::"text", 'setback'::"text"])))
);


--
-- Name: decision_feedback_pairs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."decision_feedback_pairs" AS
 SELECT "d"."id" AS "decision_id",
    "d"."session_id",
    "d"."turn_id",
    "d"."final_label",
    "d"."final_confidence",
    "d"."decided_by",
    "d"."deliberation_triggered",
    "d"."trigger_reason",
    "d"."mode",
    "d"."created_at",
    "f"."felt_seen_score",
    "f"."attunement_score",
    "f"."safety_score",
    "f"."depth_score",
    "f"."corrected_label",
    "f"."tags" AS "feedback_tags",
    "f"."comment" AS "feedback_comment",
        CASE
            WHEN ((COALESCE("f"."attunement_score", 0) >= 4) AND (COALESCE("f"."felt_seen_score", 0) >= 4)) THEN true
            ELSE false
        END AS "positive_outcome",
        CASE
            WHEN ((COALESCE("f"."attunement_score", 5) <= 2) OR (COALESCE("f"."felt_seen_score", 5) <= 2)) THEN true
            ELSE false
        END AS "negative_outcome",
        CASE
            WHEN (("f"."corrected_label" IS NOT NULL) AND ("f"."corrected_label" <> "d"."final_label")) THEN true
            ELSE false
        END AS "was_corrected"
   FROM ("public"."maia_decisions" "d"
     LEFT JOIN "public"."maia_decision_feedback" "f" ON (("f"."decision_id" = "d"."id")));


