 SELECT "d"."id" AS "deliberation_id",
    "d"."created_at",
    "d"."session_id",
    "d"."committee",
    "d"."final_classification",
    "d"."final_confidence",
    "d"."decided_by",
    "d"."votes_json",
    "d"."deliberation_ms",
    "f"."id" AS "feedback_id",
    "f"."felt_seen_score",
    "f"."attunement_score",
    "f"."safety_score",
    "f"."depth_appropriateness_score",
    "f"."rupture_mark",
    "f"."ideal_for_repair",
    "f"."tags" AS "feedback_tags",
    "f"."comment" AS "feedback_comment",
        CASE
            WHEN ((COALESCE(("f"."attunement_score")::integer, 0) >= 4) AND (COALESCE(("f"."felt_seen_score")::integer, 0) >= 4) AND (COALESCE("f"."rupture_mark", false) = false)) THEN true
            ELSE false
        END AS "positive_outcome",
        CASE
            WHEN ((COALESCE("f"."rupture_mark", false) = true) OR (COALESCE(("f"."attunement_score")::integer, 5) <= 2) OR (COALESCE(("f"."felt_seen_score")::integer, 5) <= 2)) THEN true
            ELSE false
        END AS "negative_outcome"
   FROM ("public"."deliberations" "d"
     LEFT JOIN "public"."maia_turn_feedback" "f" ON ((("f"."deliberation_id" = "d"."id") OR ("f"."turn_id" = "d"."turn_id"))))
  WHERE ("f"."id" IS NOT NULL);


