CREATE VIEW "public"."developmental_memories_with_decay" AS
 SELECT "id",
    "user_id",
    "memory_type",
    "content_text",
    "trigger_event",
    "facet_code",
    "spiral_cycle",
    "significance",
    "vector_embedding",
    "recall_count",
    "last_recalled_at",
    "entity_tags",
    "source_beads_task_id",
    "source_ain_session_id",
    "source_consciousness_entry_id",
    "visibility",
    "share_scope",
    "confirmed_by_user",
    "last_confirmed_at",
    "user_feedback",
    "valid_from",
    "valid_to",
    "formed_at",
    "public"."calculate_decayed_confidence"("significance", "memory_type", "last_confirmed_at", "formed_at") AS "effective_confidence"
   FROM "public"."developmental_memories" "dm"
  WHERE (("valid_to" IS NULL) OR ("valid_to" > "now"()));


