--
-- Name: executor_provider_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."executor_provider_stats" AS
 SELECT "provider",
    "count"(*) AS "total_runs",
    "sum"(
        CASE
            WHEN "ok" THEN 1
            ELSE 0
        END) AS "successful_runs",
    "sum"(
        CASE
            WHEN (NOT "ok") THEN 1
            ELSE 0
        END) AS "failed_runs",
    "round"(((100.0 * ("sum"(
        CASE
            WHEN "ok" THEN 1
            ELSE 0
        END))::numeric) / (NULLIF("count"(*), 0))::numeric), 2) AS "success_rate",
    "avg"("duration_ms") AS "avg_duration_ms"
   FROM "public"."ain_executor_runs"
  GROUP BY "provider";


--
-- Name: executor_recent_activity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."executor_recent_activity" AS
 SELECT "id",
    "created_at",
    "task_id",
    "provider",
    "task_type",
    "risk",
    "ok",
    "summary",
    "duration_ms",
    "user_id",
    "deliberation_id"
   FROM "public"."ain_executor_runs"
  WHERE ("created_at" >= ("now"() - '24:00:00'::interval))
  ORDER BY "created_at" DESC;


--
-- Name: executor_task_type_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."executor_task_type_stats" AS
 SELECT "task_type",
    "risk",
    "count"(*) AS "total_runs",
    "sum"(
        CASE
            WHEN "ok" THEN 1
            ELSE 0
        END) AS "successful_runs",
    "round"(((100.0 * ("sum"(
        CASE
            WHEN "ok" THEN 1
            ELSE 0
        END))::numeric) / (NULLIF("count"(*), 0))::numeric), 2) AS "success_rate",
    "avg"("duration_ms") AS "avg_duration_ms"
   FROM "public"."ain_executor_runs"
  GROUP BY "task_type", "risk"
  ORDER BY ("count"(*)) DESC;


