    "event_type" "text" DEFAULT 'insight'::"text" NOT NULL,
    "source" "text" DEFAULT 'system_detected'::"text" NOT NULL,
    "content" "text",
    "context_before" "text",
    "maia_response" "text",
    "confidence" double precision,
    "significance" double precision,
    "markers" "jsonb" DEFAULT '[]'::"jsonb",
    "decision_id" "uuid",
    "memory_id" "text",
    "episode_id" "uuid",
    "validated" boolean,
    "feedback_score" integer,
    "feedback_text" "text",
    "meta" "jsonb" DEFAULT '{}'::"jsonb"
);


--
-- Name: expansion_by_session; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."expansion_by_session" AS
 SELECT "session_id",
    "count"(*) AS "expansions",
    "count"(DISTINCT "event_type") AS "expansion_types",
    "avg"(COALESCE("confidence", (0)::double precision)) AS "avg_confidence",
    "avg"(COALESCE("significance", (0)::double precision)) AS "avg_significance",
    "array_agg"(DISTINCT "event_type") AS "types_seen",
    "min"("created_at") AS "first_expansion",
    "max"("created_at") AS "last_expansion"
   FROM "public"."expansion_events"
  GROUP BY "session_id";


--
-- Name: expansion_by_user; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."expansion_by_user" AS
 SELECT COALESCE("user_id", ("member_id")::"text") AS "user_key",
    "count"(*) AS "total_expansions",
    "count"(DISTINCT "event_type") AS "expansion_types",
    "count"(DISTINCT "session_id") AS "sessions_with_expansion",
    "avg"(COALESCE("confidence", (0)::double precision)) AS "avg_confidence",
    "avg"(COALESCE("significance", (0)::double precision)) AS "avg_significance",
    "sum"(
        CASE
            WHEN ("validated" = true) THEN 1
            ELSE 0
        END) AS "validated_count",
    "sum"(
        CASE
            WHEN ("validated" = false) THEN 1
            ELSE 0
        END) AS "invalidated_count",
    "avg"("feedback_score") AS "avg_feedback_score",
    "min"("created_at") AS "first_expansion",
    "max"("created_at") AS "last_expansion",
        CASE
            WHEN ("count"(*) > 1) THEN ((EXTRACT(epoch FROM ("max"("created_at") - "min"("created_at"))) / (("count"(*) - 1))::numeric) / 86400.0)
            ELSE NULL::numeric
        END AS "avg_days_between_expansions"
   FROM "public"."expansion_events"
  GROUP BY COALESCE("user_id", ("member_id")::"text");


--
-- Name: expansion_events_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."expansion_events_daily" AS
 SELECT ("date_trunc"('day'::"text", "created_at"))::"date" AS "day",
    "event_type",
    "source",
    "count"(*) AS "event_count",
    "avg"(COALESCE("confidence", (0)::double precision)) AS "avg_confidence",
    "avg"(COALESCE("significance", (0)::double precision)) AS "avg_significance",
    "sum"(
        CASE
            WHEN ("validated" = true) THEN 1
            ELSE 0
        END) AS "validated_count",
    "avg"("feedback_score") AS "avg_feedback_score"
   FROM "public"."expansion_events"
  GROUP BY (("date_trunc"('day'::"text", "created_at"))::"date"), "event_type", "source"
  ORDER BY (("date_trunc"('day'::"text", "created_at"))::"date") DESC, "event_type";


--
-- Name: expansion_marker_frequency; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."expansion_marker_frequency" AS
 SELECT "marker"."value" AS "marker",
    "count"(*) AS "occurrence_count",
    "count"(DISTINCT "expansion_events"."session_id") AS "sessions",
    "count"(DISTINCT COALESCE("expansion_events"."user_id", ("expansion_events"."member_id")::"text")) AS "users",
    "avg"(COALESCE("expansion_events"."significance", (0)::double precision)) AS "avg_significance"
   FROM "public"."expansion_events",
    LATERAL "jsonb_array_elements_text"("expansion_events"."markers") "marker"("value")
  GROUP BY "marker"."value"
  ORDER BY ("count"(*)) DESC;


--
-- Name: expansion_type_source_matrix; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."expansion_type_source_matrix" AS
 SELECT "event_type",
    "sum"(
        CASE
            WHEN ("source" = 'system_detected'::"text") THEN 1
            ELSE 0
        END) AS "system_detected",
    "sum"(
        CASE
            WHEN ("source" = 'user_reported'::"text") THEN 1
            ELSE 0
        END) AS "user_reported",
    "sum"(
        CASE
            WHEN ("source" = 'practitioner_noted'::"text") THEN 1
            ELSE 0
        END) AS "practitioner_noted",
    "sum"(
        CASE
            WHEN ("source" = 'memory_surfaced'::"text") THEN 1
            ELSE 0
        END) AS "memory_surfaced",
    "count"(*) AS "total"
   FROM "public"."expansion_events"
  GROUP BY "event_type"
  ORDER BY ("count"(*)) DESC;


--
-- Name: expansion_validation_accuracy; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."expansion_validation_accuracy" AS
 SELECT "source",
    "event_type",
    "count"(*) AS "total",
    "sum"(
        CASE
            WHEN ("validated" IS NULL) THEN 1
            ELSE 0
        END) AS "pending_validation",
    "sum"(
        CASE
            WHEN ("validated" = true) THEN 1
            ELSE 0
        END) AS "validated_true",
    "sum"(
        CASE
            WHEN ("validated" = false) THEN 1
            ELSE 0
        END) AS "validated_false",
    "round"(((100.0 * ("sum"(
        CASE
            WHEN ("validated" = true) THEN 1
            ELSE 0
        END))::numeric) / (NULLIF("sum"(
        CASE
            WHEN ("validated" IS NOT NULL) THEN 1
            ELSE 0
        END), 0))::numeric), 2) AS "accuracy_pct"
   FROM "public"."expansion_events"
  GROUP BY "source", "event_type"
  ORDER BY "source", ("count"(*)) DESC;


