--
-- Name: hypothesis_overview; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."hypothesis_overview" AS
 SELECT "id",
    "type",
    "priority",
    "status",
    ("trigger" ->> 'patternDescription'::"text") AS "pattern",
    ("modification" ->> 'rationale'::"text") AS "rationale",
    ("expected_outcome" ->> 'metric'::"text") AS "target_metric",
    (("expected_outcome" ->> 'targetImprovement'::"text"))::numeric AS "target_improvement",
    ("results" ->> 'verdict'::"text") AS "test_verdict",
    (("results" ->> 'improvement'::"text"))::numeric AS "actual_improvement",
    "created_at",
    "tested_at",
    "deployed_at",
    "deployed_by"
   FROM "public"."improvement_hypotheses" "h"
  ORDER BY
        CASE "status"
            WHEN 'proposed'::"public"."hypothesis_status" THEN 1
            WHEN 'testing'::"public"."hypothesis_status" THEN 2
            WHEN 'validated'::"public"."hypothesis_status" THEN 3
            WHEN 'deployed'::"public"."hypothesis_status" THEN 4
            ELSE 5
        END,
        CASE "priority"
            WHEN 'critical'::"public"."hypothesis_priority" THEN 1
            WHEN 'high'::"public"."hypothesis_priority" THEN 2
            WHEN 'medium'::"public"."hypothesis_priority" THEN 3
            ELSE 4
        END, "created_at" DESC;


