--
-- Name: maia_engine_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."maia_engine_performance" AS
 SELECT "ec"."engine_name",
    "count"(*) AS "total_responses",
    "avg"("ec"."response_time_ms") AS "avg_response_time",
    "avg"("ec"."attunement_score") AS "avg_attunement",
    "avg"(
        CASE
            WHEN ("f"."felt_seen_score" IS NOT NULL) THEN "f"."felt_seen_score"
            ELSE NULL::smallint
        END) AS "avg_helpfulness",
    "count"(
        CASE
            WHEN ("me"."id" IS NOT NULL) THEN 1
            ELSE NULL::integer
        END) AS "misattunement_count",
    "avg"(
        CASE
            WHEN ("me"."id" IS NOT NULL) THEN "me"."severity"
            ELSE NULL::smallint
        END) AS "avg_misattunement_severity"
   FROM (("public"."maia_engine_comparisons" "ec"
     LEFT JOIN "public"."maia_turn_feedback" "f" ON (("ec"."turn_id" = "f"."turn_id")))
     LEFT JOIN "public"."maia_misattunements" "me" ON (("ec"."turn_id" = "me"."turn_id")))
  WHERE ("ec"."created_at" >= ("now"() - '30 days'::interval))
  GROUP BY "ec"."engine_name";


--
-- Name: maia_gold_turns; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."maia_gold_turns" AS
 SELECT "t"."id",
    "t"."session_id",
    "t"."turn_index",
    "t"."user_text",
    "t"."maia_text",
    "t"."processing_profile",
    "t"."primary_engine",
    "t"."secondary_engine",
    "t"."used_claude_consult",
    "t"."latency_ms",
    "t"."element",
    "t"."facet",
    "t"."topic_tags",
    "t"."consciousness_layers_activated",
    "t"."consciousness_depth_achieved",
    "t"."observer_insights",
    "t"."evolution_triggers",
    "t"."rupture_flag",
    "t"."repair_flag",
    "t"."created_at",
    "f"."felt_seen_score",
    "f"."attunement_score",
    "f"."safety_score",
    "f"."depth_appropriateness_score",
    "f"."source_type" AS "feedback_source",
    "f"."tags" AS "feedback_tags",
    "f"."comment" AS "feedback_comment",
    "f"."created_at" AS "feedback_created_at"
   FROM ("public"."maia_turns" "t"
     JOIN "public"."maia_turn_feedback" "f" ON (("f"."turn_id" = "t"."id")))
  WHERE ((COALESCE(("f"."felt_seen_score")::integer, 0) >= 4) AND (COALESCE(("f"."attunement_score")::integer, 0) >= 4) AND (COALESCE(("f"."safety_score")::integer, 0) >= 4) AND (COALESCE("f"."rupture_mark", false) = false));


