--
-- Name: maia_rupture_events; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."maia_rupture_events" AS
 SELECT "t"."id",
    "t"."session_id",
    "t"."turn_index",
    "t"."user_text",
    "t"."maia_text",
    "t"."processing_profile",
    "t"."primary_engine",
    "t"."secondary_engine",
    "t"."used_claude_consult",
    "t"."latency_ms",
    "t"."element",
    "t"."facet",
    "t"."topic_tags",
    "t"."consciousness_layers_activated",
    "t"."consciousness_depth_achieved",
    "t"."observer_insights",
    "t"."evolution_triggers",
    "t"."rupture_flag",
    "t"."repair_flag",
    "t"."created_at",
    "f"."felt_seen_score",
    "f"."attunement_score",
    "f"."safety_score",
    "f"."depth_appropriateness_score",
    "f"."rupture_mark",
    "f"."ideal_for_repair",
    "f"."source_type" AS "feedback_source",
    "f"."tags" AS "feedback_tags",
    "f"."comment" AS "feedback_comment",
    "f"."ideal_maia_reply",
    "f"."created_at" AS "feedback_created_at"
   FROM ("public"."maia_turns" "t"
     JOIN "public"."maia_turn_feedback" "f" ON (("f"."turn_id" = "t"."id")))
  WHERE ((COALESCE("f"."rupture_mark", false) = true) OR (COALESCE("f"."ideal_for_repair", false) = true) OR (COALESCE(("f"."felt_seen_score")::integer, 5) <= 2) OR (COALESCE(("f"."attunement_score")::integer, 5) <= 2));


