--
-- Name: maia_voice_turns; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."maia_voice_turns" (
    "id" bigint NOT NULL,
    "turn_id" bigint,
    "session_id" "text" NOT NULL,
    "mode" "text",
    "first_byte_latency_ms" integer,
    "total_duration_ms" integer,
    "audio_length_ms" integer,
    "chunk_count" integer,
    "prosody_profile" "jsonb",
    "tts_provider" "text",
    "tts_model" "text",
    "voice_id" "text",
    "user_interrupted" boolean DEFAULT false,
    "user_requested_repeat" boolean DEFAULT false,
    "completed_listening" boolean DEFAULT true,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "maia_voice_turns_mode_check" CHECK (("mode" = ANY (ARRAY['talk'::"text", 'care'::"text", 'note'::"text"]))),
    CONSTRAINT "maia_voice_turns_tts_provider_check" CHECK (("tts_provider" = ANY (ARRAY['openai'::"text", 'xtts'::"text", 'personaplex'::"text", 'local'::"text"])))
);


--
-- Name: maia_voice_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."maia_voice_performance" AS
 SELECT "vt"."mode",
    "vt"."tts_provider",
    "count"(*) AS "sample_count",
    "avg"("vt"."first_byte_latency_ms") AS "avg_first_byte_latency",
    "avg"("vt"."total_duration_ms") AS "avg_total_duration",
    "avg"(
        CASE
            WHEN "vt"."completed_listening" THEN 1.0
            ELSE 0.0
        END) AS "completion_rate",
    "avg"(
        CASE
            WHEN "vt"."user_interrupted" THEN 1.0
            ELSE 0.0
        END) AS "interruption_rate",
    "avg"("vf"."voice_quality") AS "avg_quality_score"
   FROM ("public"."maia_voice_turns" "vt"
     LEFT JOIN "public"."maia_voice_feedback" "vf" ON (("vt"."turn_id" = "vf"."turn_id")))
  WHERE ("vt"."created_at" >= ("now"() - '30 days'::interval))
  GROUP BY "vt"."mode", "vt"."tts_provider";


