);


--
-- Name: member_authorship_metrics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."member_authorship_metrics" AS
 WITH "counts" AS (
         SELECT "e"."member_id",
            "date"("e"."created_at") AS "encounter_day",
            "count"(*) FILTER (WHERE ("e"."event_type" = 'kept'::"text")) AS "kept",
            "count"(*) FILTER (WHERE ("e"."event_type" = 'revised'::"text")) AS "revised",
            "count"(*) FILTER (WHERE ("e"."event_type" = 'discarded'::"text")) AS "discarded",
            "count"(*) FILTER (WHERE ("e"."event_type" = 'created'::"text")) AS "created",
            "count"(*) FILTER (WHERE ("e"."event_type" = 'released'::"text")) AS "released",
            "count"(*) FILTER (WHERE ("e"."event_type" = 'split'::"text")) AS "split"
           FROM "public"."member_field_note_events" "e"
          GROUP BY "e"."member_id", ("date"("e"."created_at"))
        )
 SELECT "member_id",
    "encounter_day",
    "kept",
    "revised",
    "discarded",
    "created",
    "released",
    "split",
    ((("kept" + "revised") + "discarded") + "created") AS "authorship_acts",
    "round"((("revised")::numeric / (NULLIF(("kept" + "revised"), 0))::numeric), 3) AS "reshape_ratio",
    "round"((("created")::numeric / (NULLIF(((("kept" + "revised") + "discarded") + "created"), 0))::numeric), 3) AS "origination_ratio",
    "round"((("discarded")::numeric / (NULLIF((("kept" + "revised") + "discarded"), 0))::numeric), 3) AS "rejection_rate",
    "round"((("released")::numeric / (NULLIF((("kept" + "revised") + "created"), 0))::numeric), 3) AS "release_rate"
   FROM "counts";


--
-- Name: member_authorship_delta; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."member_authorship_delta" AS
 SELECT "member_id",
    "count"(*) AS "encounters",
    "min"("encounter_day") AS "first_encounter",
    "max"("encounter_day") AS "latest_encounter",
    ("array_agg"("reshape_ratio" ORDER BY "encounter_day"))[1] AS "first_reshape_ratio",
    ("array_agg"("reshape_ratio" ORDER BY "encounter_day" DESC))[1] AS "latest_reshape_ratio",
    (("array_agg"("reshape_ratio" ORDER BY "encounter_day" DESC))[1] - ("array_agg"("reshape_ratio" ORDER BY "encounter_day"))[1]) AS "reshape_ratio_delta",
    (("array_agg"("origination_ratio" ORDER BY "encounter_day" DESC))[1] - ("array_agg"("origination_ratio" ORDER BY "encounter_day"))[1]) AS "origination_ratio_delta"
   FROM "public"."member_authorship_metrics"
  GROUP BY "member_id"
 HAVING ("count"(*) >= 2);


