--
-- Name: member_memory_atoms; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."member_memory_atoms" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "member_id" "uuid" NOT NULL,
    "source_type" "text" NOT NULL,
    "source_id" "uuid",
    "title" "text" NOT NULL,
    "body" "text",
    "primary_register" "text",
    "registers" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "elemental_lenses" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "thread_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "kept_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_touched_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "return_preference" "text" DEFAULT 'contextual_doorway'::"text" NOT NULL,
    "last_surfaced_at" timestamp with time zone,
    "surface_count" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "crossing_allowed" boolean DEFAULT false NOT NULL,
    "still_here_count" integer DEFAULT 0 NOT NULL,
    "is_breakthrough" boolean DEFAULT false,
    "marked_breakthrough_at" timestamp with time zone,
    "facilitator_id" "uuid",
    "epistemological_status" "text",
    "provenance" "jsonb",
    "memory_scope" "text" DEFAULT 'personal'::"text" NOT NULL,
    "team_id" "uuid",
    "client_id" "uuid",
    "encounter_id" "uuid",
    "member_response_status" "text",
    "member_response_at" timestamp with time zone,
    "posture_at_creation" "text" NOT NULL,
    "generated_by" "text" NOT NULL,
    CONSTRAINT "atom_client_scope_requires_client" CHECK ((("memory_scope" <> 'client'::"text") OR ("client_id" IS NOT NULL))),
    CONSTRAINT "atom_encounter_scope_requires_encounter" CHECK ((("memory_scope" <> 'encounter'::"text") OR ("encounter_id" IS NOT NULL))),
    CONSTRAINT "atom_scope_requires_team" CHECK ((("memory_scope" = 'personal'::"text") OR ("team_id" IS NOT NULL))),
    CONSTRAINT "breakthrough_flag_timestamp_coherent" CHECK (((("is_breakthrough" = true) AND ("marked_breakthrough_at" IS NOT NULL)) OR (("is_breakthrough" = false) AND ("marked_breakthrough_at" IS NULL)))),
    CONSTRAINT "crossing_must_be_false" CHECK (("crossing_allowed" = false)),
    CONSTRAINT "elemental_lenses_valid" CHECK (("elemental_lenses" <@ ARRAY['fire'::"text", 'water'::"text", 'earth'::"text", 'air'::"text", 'aether'::"text"])),
    CONSTRAINT "member_memory_atoms_epistemological_status_check" CHECK ((("epistemological_status" IS NULL) OR ("epistemological_status" = ANY (ARRAY['observed'::"text", 'reported'::"text", 'inferred'::"text", 'provisional'::"text", 'claimed'::"text"])))),
    CONSTRAINT "member_memory_atoms_generated_by_valid" CHECK (("generated_by" = ANY (ARRAY['member-gesture'::"text", 'member-utterance'::"text", 'inference'::"text", 'synthesis'::"text", 'derivation'::"text", 'practitioner-observation'::"text", 'unattributed-historical'::"text"]))),
    CONSTRAINT "member_memory_atoms_memory_scope_check" CHECK (("memory_scope" = ANY (ARRAY['personal'::"text", 'colab'::"text", 'client'::"text", 'encounter'::"text"]))),
    CONSTRAINT "member_memory_atoms_posture_valid" CHECK (("posture_at_creation" = ANY (ARRAY['normal'::"text", 'sanctuary'::"text", 'unknown-historical'::"text"]))),
    CONSTRAINT "member_memory_atoms_primary_register_check" CHECK ((("primary_register" IS NULL) OR ("primary_register" = ANY (ARRAY['episodic'::"text", 'thematic'::"text", 'developmental'::"text", 'archetypal'::"text", 'relational'::"text", 'threshold'::"text", 'witnessed'::"text", 'sacred_protected'::"text"])))),
    CONSTRAINT "member_memory_atoms_return_preference_check" CHECK (("return_preference" = ANY (ARRAY['member_pulled'::"text", 'contextual_doorway'::"text", 'ritual_review_opt_in'::"text"]))),
    CONSTRAINT "member_memory_atoms_source_type_check" CHECK (("source_type" = ANY (ARRAY['idea'::"text", 'idea_block'::"text", 'journal'::"text", 'dream'::"text", 'reflection'::"text", 'decision'::"text", 'change'::"text", 'session_excerpt'::"text", 'spontaneous'::"text", 'practitioner_observation'::"text", 'capsule'::"text"]))),
    CONSTRAINT "member_memory_atoms_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'still_alive'::"text", 'set_aside'::"text", 'protected'::"text", 'archived'::"text"]))),
    CONSTRAINT "member_memory_atoms_still_here_count_check" CHECK (("still_here_count" >= 0)),
    CONSTRAINT "member_memory_atoms_surface_count_check" CHECK (("surface_count" >= 0)),
    CONSTRAINT "member_response_coherent" CHECK (((("member_response_status" IS NULL) AND ("member_response_at" IS NULL)) OR (("member_response_status" IS NOT NULL) AND ("member_response_at" IS NOT NULL)))),
    CONSTRAINT "member_response_status_valid" CHECK ((("member_response_status" IS NULL) OR ("member_response_status" = ANY (ARRAY['confirmed'::"text", 'rejected'::"text", 'modified'::"text"])))),
    CONSTRAINT "registers_valid" CHECK (("registers" <@ ARRAY['episodic'::"text", 'thematic'::"text", 'developmental'::"text", 'archetypal'::"text", 'relational'::"text", 'threshold'::"text", 'witnessed'::"text", 'sacred_protected'::"text"])),
    CONSTRAINT "sacred_protected_register_status" CHECK (((NOT ('sacred_protected'::"text" = ANY ("registers"))) OR ("status" = 'protected'::"text"))),
    CONSTRAINT "sourcing_discipline" CHECK (((("source_type" = 'spontaneous'::"text") AND ("body" IS NOT NULL)) OR (("source_type" <> 'spontaneous'::"text") AND ("source_id" IS NOT NULL))))
);


