    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "pattern_key" "text",
    "pattern_type" "text",
    "recurrence_count" integer DEFAULT 1 NOT NULL,
    "latest_significance" numeric DEFAULT 0.5 NOT NULL,
    "average_significance" numeric DEFAULT 0.5 NOT NULL,
    "max_significance" numeric DEFAULT 0.5 NOT NULL,
    "trigger_contexts" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "supporting_insight_ids" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
