    "generated_at" timestamp with time zone,
    "resonance_response" "text",
    "member_label" "text",
    CONSTRAINT "pattern_ledger_confidence_check" CHECK ((("confidence" >= (0)::numeric) AND ("confidence" <= (1)::numeric))),
    CONSTRAINT "pattern_ledger_generation_status_check" CHECK (("generation_status" = ANY (ARRAY['pending'::"text", 'generating'::"text", 'complete'::"text", 'failed'::"text"]))),
    CONSTRAINT "pattern_ledger_pattern_type_check" CHECK (("pattern_type" = ANY (ARRAY['pattern'::"text", 'growth_edge'::"text"]))),
    CONSTRAINT "pattern_ledger_resonance_response_check" CHECK (("resonance_response" = ANY (ARRAY['fits'::"text", 'partly'::"text", 'not_now'::"text", 'no'::"text", 'explore'::"text"]))),
    CONSTRAINT "pattern_ledger_scope_check" CHECK (("scope" = ANY (ARRAY['relationship'::"text", 'work'::"text", 'somatic'::"text", 'spiritual'::"text", 'recurring_trigger'::"text", 'theme'::"text"]))),
    CONSTRAINT "pattern_ledger_status_check" CHECK (("status" = ANY (ARRAY['emerging'::"text", 'offered'::"text", 'confirmed'::"text", 'partial'::"text", 'rejected'::"text", 'retired'::"text"])))
);


