);


--
-- Name: pattern_offering_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."pattern_offering_stats" AS
 SELECT "member_id",
    "count"(*) FILTER (WHERE ("status" = 'confirmed'::"text")) AS "confirmed_count",
    "count"(*) FILTER (WHERE ("status" = 'rejected'::"text")) AS "rejected_count",
    "count"(*) FILTER (WHERE ("status" = 'partial'::"text")) AS "partial_count",
    "count"(*) FILTER (WHERE ("status" = 'emerging'::"text")) AS "emerging_count",
    "avg"("confidence") FILTER (WHERE ("status" = 'confirmed'::"text")) AS "avg_confirmed_confidence"
   FROM "public"."pattern_ledger"
  GROUP BY "member_id";


