    "promoted_from" "uuid",
    "lifecycle" "text" DEFAULT 'completed'::"text" NOT NULL,
    "completion_mode" "text",
    "completed_at" timestamp with time zone,
    "version" integer DEFAULT 1 NOT NULL,
    "session_id" "uuid",
    CONSTRAINT "practitioner_client_notes_completed_at_check" CHECK (((("completion_mode" = 'practitioner_declared'::"text") AND ("completed_at" IS NOT NULL)) OR (("completion_mode" IS DISTINCT FROM 'practitioner_declared'::"text") AND ("completed_at" IS NULL)))),
    CONSTRAINT "practitioner_client_notes_completion_mode_check" CHECK (((("lifecycle" = 'draft'::"text") AND ("completion_mode" IS NULL)) OR (("lifecycle" = 'completed'::"text") AND ("completion_mode" = ANY (ARRAY['backfilled'::"text", 'practitioner_declared'::"text"]))))),
    CONSTRAINT "practitioner_client_notes_draft_kind_check" CHECK ((("lifecycle" = 'completed'::"text") OR ("kind" = 'note'::"text"))),
    CONSTRAINT "practitioner_client_notes_kind_check" CHECK (("kind" = ANY (ARRAY['note'::"text", 'commitment'::"text", 'recognition'::"text", 'detail'::"text"]))),
    CONSTRAINT "practitioner_client_notes_lifecycle_check" CHECK (("lifecycle" = ANY (ARRAY['draft'::"text", 'completed'::"text"]))),
    CONSTRAINT "practitioner_client_notes_status_check" CHECK (((("kind" = 'commitment'::"text") AND ("status" IS NOT NULL) AND ("status" = ANY (ARRAY['alive'::"text", 'completed'::"text", 'released'::"text"]))) OR (("kind" <> 'commitment'::"text") AND ("status" IS NULL))))
);


