    CONSTRAINT "preference_confirmations_triggered_by_check" CHECK (("triggered_by" = ANY (ARRAY['manual'::"text", 'prompt'::"text", 'drift_detected'::"text", 'session_start'::"text"])))
);


--
-- Name: prescient_dissent; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."prescient_dissent" AS
 SELECT "d"."id" AS "decision_id",
    "d"."final_label",
    "f"."corrected_label",
    "v"."member",
    "v"."label" AS "member_vote",
    "v"."confidence" AS "member_confidence",
    "v"."rationale",
    "d"."created_at"
   FROM (("public"."maia_decisions" "d"
     JOIN "public"."maia_decision_feedback" "f" ON (("f"."decision_id" = "d"."id")))
     JOIN "public"."maia_decision_votes" "v" ON (("v"."decision_id" = "d"."id")))
  WHERE (("f"."corrected_label" IS NOT NULL) AND ("v"."label" = "f"."corrected_label") AND ("d"."final_label" <> "f"."corrected_label"))
  ORDER BY "d"."created_at" DESC;


