--
-- Name: safe_referral_requests; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."safe_referral_requests" AS
 SELECT "rr"."id",
    "rr"."from_practitioner_id",
    "rr"."to_practitioner_id",
    "rr"."connection_id",
    "rr"."status",
    "rr"."client_age_range",
    "rr"."client_pronouns",
    "rr"."presenting_themes",
    "rr"."urgency",
    "rr"."constraints",
    "rr"."requester_note",
    "rr"."client_consent_given",
    "rr"."client_name_shared",
    "rr"."client_name",
    "rr"."client_contact",
    "rr"."consent_recorded_at",
    "rr"."recipient_note",
    "rr"."created_at",
    "rr"."sent_at",
    "rr"."viewed_at",
    "rr"."responded_at",
    "rr"."sealed_at",
    "rr"."sealed_reason"
   FROM ("public"."referral_requests" "rr"
     JOIN "public"."practitioner_connections" "pc" ON (("pc"."id" = "rr"."connection_id")))
  WHERE (("rr"."sealed_at" IS NULL) AND ("pc"."status" = 'accepted'::"text"));


