    "confidence" numeric(3,2) DEFAULT 0.5 NOT NULL,
    "kairos_assessment" character varying(20) DEFAULT 'stable'::character varying NOT NULL,
    "kairos_confidence" numeric(3,2) DEFAULT 0.5 NOT NULL,
    "kairos_description" "text",
    "movement" "jsonb" DEFAULT '{"exiting": [], "entering": [], "velocity": 0.0, "trajectory": "still"}'::"jsonb" NOT NULL,
    "evidence" "jsonb" DEFAULT '{"gaps": [], "observations": [], "contradictions": []}'::"jsonb" NOT NULL,
    "raw_text" "text",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "state_vectors_confidence_check" CHECK ((("confidence" >= 0.0) AND ("confidence" <= 1.0))),
    CONSTRAINT "state_vectors_kairos_assessment_check" CHECK ((("kairos_assessment")::"text" = ANY (ARRAY[('stable'::character varying)::"text", ('transition'::character varying)::"text", ('threshold'::character varying)::"text", ('integration'::character varying)::"text", ('collapse-risk'::character varying)::"text"]))),
    CONSTRAINT "state_vectors_kairos_confidence_check" CHECK ((("kairos_confidence" >= 0.0) AND ("kairos_confidence" <= 1.0))),
    CONSTRAINT "state_vectors_primary_element_check" CHECK ((("primary_element")::"text" = ANY (ARRAY[('earth'::character varying)::"text", ('water'::character varying)::"text", ('fire'::character varying)::"text", ('air'::character varying)::"text", ('aether'::character varying)::"text"]))),
    CONSTRAINT "state_vectors_primary_intensity_check" CHECK ((("primary_intensity")::"text" = ANY (ARRAY[('low'::character varying)::"text", ('medium'::character varying)::"text", ('high'::character varying)::"text"]))),
    CONSTRAINT "state_vectors_primary_phase_check" CHECK ((("primary_phase" IS NULL) OR (("primary_phase")::"text" = ANY (ARRAY[('entering'::character varying)::"text", ('in'::character varying)::"text", ('exiting'::character varying)::"text"])))),
    CONSTRAINT "state_vectors_primary_polarity_check" CHECK ((("primary_polarity" >= 1) AND ("primary_polarity" <= 5))),
    CONSTRAINT "state_vectors_primary_stability_check" CHECK ((("primary_stability" >= 1) AND ("primary_stability" <= 5))),
    CONSTRAINT "state_vectors_secondary_element_check" CHECK ((("secondary_element" IS NULL) OR (("secondary_element")::"text" = ANY (ARRAY[('earth'::character varying)::"text", ('water'::character varying)::"text", ('fire'::character varying)::"text", ('air'::character varying)::"text", ('aether'::character varying)::"text"])))),
    CONSTRAINT "state_vectors_source_check" CHECK ((("source")::"text" = ANY (ARRAY[('checkin'::character varying)::"text", ('conversation'::character varying)::"text", ('auto-detected'::character varying)::"text", ('voice-analysis'::character varying)::"text", ('journal'::character varying)::"text"])))
);


