--
-- Name: usage_ledger; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."usage_ledger" AS
 SELECT 'usage_events'::"text" AS "source",
    ("usage_events"."id")::"text" AS "event_id",
    "usage_events"."member_id",
    "usage_events"."is_sanctuary",
    "usage_events"."kind",
    "usage_events"."route",
    "usage_events"."tier",
    "usage_events"."provider",
    "usage_events"."model",
    "usage_events"."processing_profile",
    "usage_events"."input_tokens",
    "usage_events"."output_tokens",
    "usage_events"."cache_creation_tokens",
    "usage_events"."cache_read_tokens",
    "usage_events"."audio_seconds",
    "usage_events"."audio_bytes",
    "usage_events"."cost_micros",
    "usage_events"."created_at"
   FROM "public"."usage_events"
UNION ALL
 SELECT 'audio_usage_events'::"text" AS "source",
    ("audio_usage_events"."id")::"text" AS "event_id",
    ("audio_usage_events"."member_id")::"text" AS "member_id",
    false AS "is_sanctuary",
        CASE
            WHEN ("audio_usage_events"."kind" ~~* '%transcri%'::"text") THEN 'voice_stt'::"text"
            ELSE 'voice_tts'::"text"
        END AS "kind",
    "audio_usage_events"."route",
    NULL::"text" AS "tier",
    COALESCE(("audio_usage_events"."meta" ->> 'provider'::"text"), 'audio'::"text") AS "provider",
    NULL::"text" AS "model",
    NULL::"text" AS "processing_profile",
    NULL::integer AS "input_tokens",
    NULL::integer AS "output_tokens",
    NULL::integer AS "cache_creation_tokens",
    NULL::integer AS "cache_read_tokens",
    "audio_usage_events"."seconds" AS "audio_seconds",
    "audio_usage_events"."bytes" AS "audio_bytes",
    (0)::bigint AS "cost_micros",
    "audio_usage_events"."created_at"
   FROM "public"."audio_usage_events";


