    "total_sessions" integer DEFAULT 0,
    "relationship_depth" double precision DEFAULT 0.0,
    "consciousness_journey_stage" "text" DEFAULT 'beginning'::"text",
    "spiral_velocity" double precision DEFAULT 0.0,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "spiral_states" "jsonb" DEFAULT '[]'::"jsonb",
    "spiral_states_updated_at" timestamp with time zone,
    "visibility" "text" DEFAULT 'private'::"text" NOT NULL,
    CONSTRAINT "user_relationship_context_visibility_check" CHECK (("visibility" = ANY (ARRAY['private'::"text", 'shared'::"text", 'commons'::"text", 'anonymized'::"text"])))
);


--
-- Name: user_session_patterns; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."user_session_patterns" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "text" NOT NULL,
    "session_id" "text" NOT NULL,
    "session_start" timestamp with time zone DEFAULT "now"(),
    "session_end" timestamp with time zone,
    "conversation_themes" "text"[],
    "emotional_patterns" "jsonb",
