    "integration_challenges_addressed" "text"[],
    "session_embedding" "public"."vector"(1536),
    "key_insights_embedding" "public"."vector"(1536),
    "field_resonance_patterns" "jsonb",
    "session_quality_score" double precision DEFAULT 0.5,
    "consciousness_coherence" double precision DEFAULT 0.5,
    "developmental_progress" double precision DEFAULT 0.5,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"()
);


--
-- Name: v_client_unread_counts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_client_unread_counts" AS
 SELECT "practitioner_id",
    "client_id",
    "count"(*) AS "unread_count",
    "count"(*) FILTER (WHERE (("urgency" = 'safety_concern'::"text") AND ("safety_reviewed" = false))) AS "safety_count",
    "max"("created_at") AS "latest_message_at"
   FROM "public"."client_messages"
  WHERE (("status" = 'sent'::"text") AND ("direction" = 'client_to_practitioner'::"text"))
  GROUP BY "practitioner_id", "client_id";


--
-- Name: v_comms_analysis_queue_status; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_comms_analysis_queue_status" AS
 SELECT "status",
    "count"(*) AS "count",
    "min"("queued_at") AS "oldest_queued",
    "max"("queued_at") AS "newest_queued",
    ("avg"(EXTRACT(epoch FROM ("finished_at" - "started_at"))))::numeric(10,2) AS "avg_processing_seconds"
   FROM "public"."comms_analysis_queue"
  GROUP BY "status";


--
-- Name: v_legacy_client_messages; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_legacy_client_messages" AS
 SELECT "m"."id",
    "t"."client_id",
    "t"."practitioner_id",
        CASE "m"."sender_type"
            WHEN 'client'::"text" THEN 'client_to_practitioner'::"text"
            WHEN 'practitioner'::"text" THEN 'practitioner_to_client'::"text"
            ELSE 'client_to_practitioner'::"text"
        END AS "direction",
        CASE "m"."message_type"
            WHEN 'reflection'::"text" THEN 'reflection'::"text"
            WHEN 'question'::"text" THEN 'question'::"text"
            WHEN 'win'::"text" THEN 'win'::"text"
            WHEN 'struggle'::"text" THEN 'struggle'::"text"
            WHEN 'logistics'::"text" THEN 'logistics'::"text"
            WHEN 'reply'::"text" THEN 'reply'::"text"
            ELSE 'reflection'::"text"
        END AS "message_type",
        CASE "m"."urgency"
            WHEN 'normal'::"text" THEN 'not_urgent'::"text"
            WHEN 'time_sensitive'::"text" THEN 'time_sensitive'::"text"
            WHEN 'safety_concern'::"text" THEN 'safety_concern'::"text"
            ELSE 'not_urgent'::"text"
        END AS "urgency",
    COALESCE("m"."body", ''::"text") AS "body",
    "m"."is_quick_response",
    "m"."quick_response_type",
    "m"."reply_to_id",
        CASE "m"."delivery_status"
            WHEN 'sent'::"text" THEN 'sent'::"text"
            WHEN 'delivered'::"text" THEN 'sent'::"text"
            WHEN 'read'::"text" THEN 'read'::"text"
            WHEN 'failed'::"text" THEN 'sent'::"text"
            ELSE 'sent'::"text"
        END AS "status",
    "m"."read_at",
    (EXISTS ( SELECT 1
           FROM "public"."comms_safety_flags" "sf"
          WHERE (("sf"."message_id" = "m"."id") AND ("sf"."acknowledged_at" IS NOT NULL)))) AS "safety_reviewed",
    ( SELECT "sf"."acknowledged_at"
           FROM "public"."comms_safety_flags" "sf"
          WHERE (("sf"."message_id" = "m"."id") AND ("sf"."acknowledged_at" IS NOT NULL))
         LIMIT 1) AS "safety_reviewed_at",
    ( SELECT "sf"."acknowledged_by"
           FROM "public"."comms_safety_flags" "sf"
          WHERE (("sf"."message_id" = "m"."id") AND ("sf"."acknowledged_at" IS NOT NULL))
         LIMIT 1) AS "safety_reviewed_by",
    "m"."created_at",
    "m"."updated_at",
    "m"."body_enc",
    "m"."body_enc_meta"
   FROM ("public"."comms_messages" "m"
     JOIN "public"."comms_threads" "t" ON (("m"."thread_id" = "t"."id")))
  WHERE (("t"."domain" = 'clinical'::"text") AND ("t"."thread_type" = ANY (ARRAY['between_session'::"text", 'session_prep'::"text", 'safety_followup'::"text"])));


--
-- Name: v_legacy_client_unread_counts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_legacy_client_unread_counts" AS
 SELECT "t"."practitioner_id",
    "t"."client_id",
    "count"(*) FILTER (WHERE (("m"."delivery_status" = ANY (ARRAY['sent'::"text", 'delivered'::"text"])) AND ("m"."sender_type" = 'client'::"text"))) AS "unread_count",
    "count"(*) FILTER (WHERE (("m"."urgency" = 'safety_concern'::"text") AND ("m"."sender_type" = 'client'::"text") AND (NOT (EXISTS ( SELECT 1
           FROM "public"."comms_safety_flags" "sf"
          WHERE (("sf"."message_id" = "m"."id") AND ("sf"."acknowledged_at" IS NOT NULL))))))) AS "safety_count",
    "max"("m"."created_at") AS "latest_message_at"
   FROM ("public"."comms_threads" "t"
     JOIN "public"."comms_messages" "m" ON (("m"."thread_id" = "t"."id")))
  WHERE (("t"."domain" = 'clinical'::"text") AND ("t"."thread_type" = ANY (ARRAY['between_session'::"text", 'session_prep'::"text", 'safety_followup'::"text"])))
  GROUP BY "t"."practitioner_id", "t"."client_id";


--
-- Name: v_legacy_message_policies; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_legacy_message_policies" AS
 SELECT "id",
    "practitioner_id",
    "client_id",
    COALESCE("check_days", ARRAY['monday'::"text", 'tuesday'::"text", 'wednesday'::"text", 'thursday'::"text", 'friday'::"text"]) AS "check_days",
    COALESCE("check_window_start", '09:00:00'::time without time zone) AS "check_window_start",
    COALESCE("check_window_end", '17:00:00'::time without time zone) AS "check_window_end",
    COALESCE("timezone", 'America/New_York'::"text") AS "timezone",
    COALESCE("max_response_hours", 48) AS "max_response_hours",
    COALESCE("crisis_copy", 'This is not monitored 24/7. If you are in crisis, please call 988 or text HOME to 741741.'::"text") AS "crisis_copy",
    "allow_inbound" AS "allow_client_messages",
    "allow_outbound" AS "allow_practitioner_reply",
    "is_active",
    "created_at",
    "updated_at"
   FROM "public"."comms_policies" "p"
  WHERE ("domain" = 'clinical'::"text");


--
-- Name: v_legacy_messages_since_last_session; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_legacy_messages_since_last_session" AS
 SELECT "t"."client_id",
    "t"."practitioner_id",
    "m"."id" AS "message_id",
        CASE "m"."sender_type"
            WHEN 'client'::"text" THEN 'client_to_practitioner'::"text"
            WHEN 'practitioner'::"text" THEN 'practitioner_to_client'::"text"
            ELSE 'client_to_practitioner'::"text"
        END AS "direction",
    "m"."message_type",
        CASE "m"."urgency"
            WHEN 'normal'::"text" THEN 'not_urgent'::"text"
            WHEN 'time_sensitive'::"text" THEN 'time_sensitive'::"text"
            WHEN 'safety_concern'::"text" THEN 'safety_concern'::"text"
            ELSE 'not_urgent'::"text"
        END AS "urgency",
    "m"."body",
        CASE "m"."delivery_status"
            WHEN 'sent'::"text" THEN 'sent'::"text"
            WHEN 'delivered'::"text" THEN 'sent'::"text"
            WHEN 'read'::"text" THEN 'read'::"text"
            ELSE 'sent'::"text"
        END AS "status",
    "m"."created_at"
   FROM (("public"."comms_threads" "t"
     JOIN "public"."comms_messages" "m" ON (("m"."thread_id" = "t"."id")))
     JOIN "public"."practitioner_clients" "pc" ON (("t"."client_id" = "pc"."id")))
  WHERE (("t"."domain" = 'clinical'::"text") AND ("t"."thread_type" = ANY (ARRAY['between_session'::"text", 'session_prep'::"text", 'safety_followup'::"text"])) AND ("m"."created_at" > COALESCE("pc"."last_session_at", "pc"."created_at")))
  ORDER BY "m"."created_at" DESC;


--
-- Name: v_legacy_safety_concern_logs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_legacy_safety_concern_logs" AS
 SELECT "sf"."id",
    "t"."practitioner_id",
    "t"."client_id",
    "sf"."message_id",
    "sf"."created_at" AS "logged_at",
    'sent'::"text" AS "email_status",
    true AS "email_sent",
    "sf"."created_at" AS "email_sent_at",
    NULL::"text" AS "email_error",
    "sf"."acknowledged_at",
    "sf"."acknowledged_by",
    "sf"."created_at",
    "sf"."review_note"
   FROM ("public"."comms_safety_flags" "sf"
     JOIN "public"."comms_threads" "t" ON (("sf"."thread_id" = "t"."id")))
  WHERE ("sf"."severity" = ANY (ARRAY['red'::"text", 'crisis'::"text"]));


--
-- Name: v_member_lens_passes_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_member_lens_passes_summary" AS
 SELECT "lens",
    "count"(*) AS "pass_count",
    "count"(DISTINCT "member_id") AS "member_count",
    "count"(DISTINCT "memory_atom_id") AS "atom_count",
    "min"("created_at") AS "earliest_pass",
    "max"("created_at") AS "latest_pass"
   FROM "public"."member_lens_passes"
  GROUP BY "lens"
  ORDER BY "lens";


--
-- Name: v_member_memory_atoms_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_member_memory_atoms_summary" AS
 SELECT "source_type",
    "primary_register",
    "status",
    "count"(*) AS "atom_count",
    "count"(DISTINCT "member_id") AS "member_count",
    "min"("kept_at") AS "earliest_keep",
    "max"("kept_at") AS "latest_keep"
   FROM "public"."member_memory_atoms"
  GROUP BY "source_type", "primary_register", "status"
  ORDER BY "source_type", "primary_register", "status";


--
-- Name: v_member_spiral_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_member_spiral_summary" AS
 SELECT "dominant_element",
    "phase",
    "relational_phase",
    "count"(*) AS "member_count",
    ("avg"("autonomy_streak"))::numeric(5,1) AS "avg_autonomy_streak",
    ("avg"("return_count"))::numeric(5,1) AS "avg_return_count",
    "max"("updated_at") AS "last_updated"
   FROM "public"."member_spiral_state"
  GROUP BY "dominant_element", "phase", "relational_phase"
  ORDER BY "dominant_element", "phase";


--
-- Name: v_member_trajectory; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_member_trajectory" AS
 SELECT "tf"."member_id",
    "m"."name" AS "member_name",
    "tf"."domain",
    "tf"."intention",
    "tf"."element_tone",
    "tf"."updated_at"
   FROM ("public"."trajectory_focus" "tf"
     LEFT JOIN "public"."members" "m" ON (("m"."id" = "tf"."member_id")))
  ORDER BY "tf"."updated_at" DESC;


--
-- Name: v_messages_since_last_session; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_messages_since_last_session" AS
 SELECT "cm"."client_id",
    "cm"."practitioner_id",
    "cm"."id" AS "message_id",
    "cm"."direction",
    "cm"."message_type",
    "cm"."urgency",
    "cm"."body",
    "cm"."status",
    "cm"."created_at"
   FROM ("public"."client_messages" "cm"
     JOIN "public"."practitioner_clients" "pc" ON (("cm"."client_id" = "pc"."id")))
  WHERE ("cm"."created_at" > COALESCE("pc"."last_session_at", "pc"."created_at"))
  ORDER BY "cm"."created_at" DESC;


--
-- Name: v_rl_agreements_pending; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_rl_agreements_pending" AS
 SELECT "p"."id" AS "practice_id",
    "count"(*) AS "pending_agreements"
   FROM (("public"."rl_practices" "p"
     JOIN "public"."rl_containers" "rc" ON (("rc"."practice_id" = "p"."id")))
     JOIN "public"."rl_agreements" "a" ON (("a"."container_id" = "rc"."id")))
  WHERE ("a"."status" = ANY (ARRAY['draft'::"public"."agreement_status", 'sent'::"public"."agreement_status"]))
  GROUP BY "p"."id";


--
-- Name: v_rl_billing_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_rl_billing_summary" AS
 SELECT "p"."id" AS "practice_id",
    "sum"(
        CASE
            WHEN (("b"."status" = 'paid'::"public"."billing_status") AND ("b"."paid_at" >= "date_trunc"('month'::"text", "now"()))) THEN "b"."amount_cents"
            ELSE 0
        END) AS "paid_this_month_cents",
    "sum"(
        CASE
            WHEN ("b"."status" = ANY (ARRAY['draft'::"public"."billing_status", 'sent'::"public"."billing_status"])) THEN "b"."amount_cents"
            ELSE 0
        END) AS "pending_cents",
    "count"(*) FILTER (WHERE ("b"."status" = ANY (ARRAY['draft'::"public"."billing_status", 'sent'::"public"."billing_status"]))) AS "outstanding_count"
   FROM (("public"."rl_practices" "p"
     LEFT JOIN "public"."rl_containers" "rc" ON (("rc"."practice_id" = "p"."id")))
     LEFT JOIN "public"."rl_billing" "b" ON (("b"."container_id" = "rc"."id")))
  GROUP BY "p"."id";


--
-- Name: v_rl_care_horizon; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_rl_care_horizon" AS
 SELECT "p"."id" AS "practice_id",
    "s"."id" AS "item_id",
    "s"."scheduled_start_at",
    ("s"."session_type")::"text" AS "item_subtype",
    "rc"."id" AS "container_id",
    "rc"."scope" AS "container_scope",
    'session'::"text" AS "item_type"
   FROM (("public"."rl_sessions" "s"
     JOIN "public"."rl_containers" "rc" ON (("s"."container_id" = "rc"."id")))
     JOIN "public"."rl_practices" "p" ON (("rc"."practice_id" = "p"."id")))
  WHERE (("s"."status" = 'scheduled'::"public"."rl_session_status") AND (("s"."scheduled_start_at" >= "now"()) AND ("s"."scheduled_start_at" <= ("now"() + '14 days'::interval))))
UNION ALL
 SELECT "t"."practice_id",
    "t"."id" AS "item_id",
    "t"."due_at" AS "scheduled_start_at",
    NULL::"text" AS "item_subtype",
    "t"."container_id",
    "t"."title" AS "container_scope",
    'task'::"text" AS "item_type"
   FROM "public"."rl_tasks" "t"
  WHERE (("t"."status" = 'open'::"public"."rl_task_status") AND (("t"."due_at" >= "now"()) AND ("t"."due_at" <= ("now"() + '14 days'::interval))))
  ORDER BY 3;


--
-- Name: v_rl_containers_needing_attention; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_rl_containers_needing_attention" AS
SELECT
    NULL::"uuid" AS "practice_id",
    NULL::"uuid" AS "container_id",
    NULL::"public"."container_status" AS "status",
    NULL::"text" AS "scope",
    NULL::timestamp with time zone AS "updated_at",
    NULL::timestamp with time zone AS "last_session",
    NULL::"text" AS "attention_reason";


--
-- Name: v_rl_pipeline_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_rl_pipeline_summary" AS
 SELECT "practice_id",
    "stage",
    "count"(*) AS "count",
    "sum"("estimated_value_cents") AS "total_value_cents",
    "sum"((("estimated_value_cents" * "probability") / 100)) AS "weighted_value_cents"
   FROM "public"."rl_opportunities"
  WHERE ("stage" <> ALL (ARRAY['won'::"public"."opportunity_stage", 'lost'::"public"."opportunity_stage"]))
  GROUP BY "practice_id", "stage";


--
-- Name: v_rl_practice_commitments; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_rl_practice_commitments" AS
 SELECT "practice_id",
    "count"(*) FILTER (WHERE ("status" = 'active'::"public"."container_status")) AS "active_containers",
    "count"(*) FILTER (WHERE ("status" = 'paused'::"public"."container_status")) AS "paused_containers",
    "count"(*) FILTER (WHERE ("status" = 'closing'::"public"."container_status")) AS "closing_containers",
    "count"(*) FILTER (WHERE ("status" = 'inquiry'::"public"."container_status")) AS "inquiry_containers"
   FROM "public"."rl_containers"
  WHERE ("status" = ANY (ARRAY['active'::"public"."container_status", 'paused'::"public"."container_status", 'closing'::"public"."container_status", 'inquiry'::"public"."container_status"]))
  GROUP BY "practice_id";


--
-- Name: v_rl_upcoming_meetings; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_rl_upcoming_meetings" AS
 SELECT "m"."practice_id",
    "m"."id" AS "meeting_id",
    "m"."title",
    "m"."meeting_type",
    "m"."scheduled_start_at",
    "m"."scheduled_end_at",
    "m"."location",
    "m"."venture_id",
    "v"."name" AS "venture_name",
    "m"."opportunity_id",
    "o"."title" AS "opportunity_title",
    ( SELECT "count"(*) AS "count"
           FROM "public"."rl_meeting_attendees" "ma"
          WHERE ("ma"."meeting_id" = "m"."id")) AS "attendee_count"
   FROM (("public"."rl_meetings" "m"
     LEFT JOIN "public"."rl_ventures" "v" ON (("v"."id" = "m"."venture_id")))
     LEFT JOIN "public"."rl_opportunities" "o" ON (("o"."id" = "m"."opportunity_id")))
  WHERE (("m"."status" = 'scheduled'::"public"."meeting_status") AND (("m"."scheduled_start_at" >= "now"()) AND ("m"."scheduled_start_at" <= ("now"() + '14 days'::interval))))
  ORDER BY "m"."scheduled_start_at";


--
-- Name: v_rl_venture_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_rl_venture_dashboard" AS
 SELECT "v"."id" AS "venture_id",
    "v"."practice_id",
    "v"."name",
    "v"."venture_type",
    "v"."description",
    "v"."created_at",
    "v"."updated_at",
    COALESCE("t"."open_tasks", (0)::bigint) AS "open_tasks",
    COALESCE("m"."upcoming_meetings", (0)::bigint) AS "upcoming_meetings",
    COALESCE("o"."active_opportunities", (0)::bigint) AS "active_opportunities",
    COALESCE("o"."pipeline_value_cents", (0)::bigint) AS "pipeline_value_cents"
   FROM ((("public"."rl_ventures" "v"
     LEFT JOIN ( SELECT "rl_tasks"."venture_id",
            "count"(*) AS "open_tasks"
           FROM "public"."rl_tasks"
          WHERE (("rl_tasks"."status" = 'open'::"public"."rl_task_status") AND ("rl_tasks"."venture_id" IS NOT NULL))
          GROUP BY "rl_tasks"."venture_id") "t" ON (("t"."venture_id" = "v"."id")))
     LEFT JOIN ( SELECT "rl_meetings"."venture_id",
            "count"(*) AS "upcoming_meetings"
           FROM "public"."rl_meetings"
          WHERE (("rl_meetings"."status" = 'scheduled'::"public"."meeting_status") AND (("rl_meetings"."scheduled_start_at" >= "now"()) AND ("rl_meetings"."scheduled_start_at" <= ("now"() + '14 days'::interval))) AND ("rl_meetings"."venture_id" IS NOT NULL))
          GROUP BY "rl_meetings"."venture_id") "m" ON (("m"."venture_id" = "v"."id")))
     LEFT JOIN ( SELECT "rl_opportunities"."venture_id",
            "count"(*) AS "active_opportunities",
            "sum"("rl_opportunities"."estimated_value_cents") AS "pipeline_value_cents"
           FROM "public"."rl_opportunities"
          WHERE (("rl_opportunities"."stage" <> ALL (ARRAY['won'::"public"."opportunity_stage", 'lost'::"public"."opportunity_stage"])) AND ("rl_opportunities"."venture_id" IS NOT NULL))
          GROUP BY "rl_opportunities"."venture_id") "o" ON (("o"."venture_id" = "v"."id")));


--
-- Name: v_rl_venture_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_rl_venture_summary" AS
 SELECT "practice_id",
    "venture_type",
    "count"(*) FILTER (WHERE ("status" = 'active'::"public"."venture_status")) AS "active_count",
    "count"(*) FILTER (WHERE ("status" = 'planning'::"public"."venture_status")) AS "planning_count",
    "count"(*) FILTER (WHERE ("status" = 'on_hold'::"public"."venture_status")) AS "on_hold_count",
    "count"(*) FILTER (WHERE ("status" = 'idea'::"public"."venture_status")) AS "idea_count",
    "count"(*) FILTER (WHERE ("status" = 'completed'::"public"."venture_status")) AS "completed_count"
   FROM "public"."rl_ventures"
  GROUP BY "practice_id", "venture_type";


--
-- Name: v_room_field_state; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_room_field_state" AS
 SELECT "r"."id" AS "room_id",
    "r"."slug",
    "r"."name",
    "count"("rm"."id") FILTER (WHERE ((("rm"."status")::"text" = 'present'::"text") AND ("rm"."left_at" IS NULL))) AS "present_count",
        CASE
            WHEN ("count"("rm"."id") FILTER (WHERE ((("rm"."status")::"text" = 'present'::"text") AND ("rm"."left_at" IS NULL))) >= 5) THEN "jsonb_build_object"('earth', "count"(*) FILTER (WHERE (("sv"."primary_element")::"text" = 'earth'::"text")), 'water', "count"(*) FILTER (WHERE (("sv"."primary_element")::"text" = 'water'::"text")), 'fire', "count"(*) FILTER (WHERE (("sv"."primary_element")::"text" = 'fire'::"text")), 'air', "count"(*) FILTER (WHERE (("sv"."primary_element")::"text" = 'air'::"text")), 'aether', "count"(*) FILTER (WHERE (("sv"."primary_element")::"text" = 'aether'::"text")))
            ELSE NULL::"jsonb"
        END AS "element_distribution",
        CASE
            WHEN ("count"("rm"."id") FILTER (WHERE ((("rm"."status")::"text" = 'present'::"text") AND ("rm"."left_at" IS NULL))) >= 5) THEN 'readable'::"text"
            ELSE 'forming'::"text"
        END AS "field_status"
   FROM (("public"."commons_rooms" "r"
     LEFT JOIN "public"."commons_room_members" "rm" ON (("rm"."room_id" = "r"."id")))
     LEFT JOIN LATERAL ( SELECT "sv2"."primary_element"
           FROM "public"."state_vectors" "sv2"
          WHERE ("sv2"."member_id" = "rm"."member_id")
          ORDER BY "sv2"."created_at" DESC
         LIMIT 1) "sv" ON (((("rm"."status")::"text" = 'present'::"text") AND ("rm"."left_at" IS NULL))))
  WHERE (("r"."status")::"text" = 'active'::"text")
  GROUP BY "r"."id", "r"."slug", "r"."name";


--
-- Name: v_rooms_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_rooms_summary" AS
SELECT
    NULL::"uuid" AS "id",
    NULL::character varying(80) AS "slug",
    NULL::character varying(120) AS "name",
    NULL::"text" AS "description",
    NULL::"text" AS "purpose",
    NULL::character varying(30) AS "room_type",
    NULL::character varying(10) AS "element",
    NULL::character varying(20) AS "status",
    NULL::character varying(20) AS "join_policy",
    NULL::character varying(20) AS "visibility",
    NULL::integer AS "max_members",
    NULL::bigint AS "present_count",
    NULL::bigint AS "events_this_week",
    NULL::timestamp with time zone AS "last_activity_at";


--
-- Name: v_state_vector_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_state_vector_daily" AS
 SELECT "date_trunc"('day'::"text", "created_at") AS "day",
    "member_id",
    "primary_element",
    "count"(*) AS "readings",
    "round"("avg"("primary_polarity"), 1) AS "avg_polarity",
    "round"("avg"("primary_stability"), 1) AS "avg_stability",
    "round"("avg"("confidence"), 2) AS "avg_confidence",
    "mode"() WITHIN GROUP (ORDER BY "kairos_assessment") AS "dominant_kairos",
    "mode"() WITHIN GROUP (ORDER BY "primary_intensity") AS "dominant_intensity"
   FROM "public"."state_vectors"
  GROUP BY ("date_trunc"('day'::"text", "created_at")), "member_id", "primary_element"
  ORDER BY ("date_trunc"('day'::"text", "created_at")) DESC;


--
-- Name: v_state_vector_history; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_state_vector_history" AS
 SELECT "sv"."id",
    "sv"."member_id",
    "m"."name" AS "member_name",
    "sv"."source",
    "sv"."primary_element",
    "sv"."primary_facet_code",
    "sv"."primary_phase",
    "sv"."primary_intensity",
    "sv"."primary_polarity",
    "sv"."primary_stability",
    "sv"."secondary_element",
    "sv"."confidence",
    "sv"."kairos_assessment",
    "sv"."kairos_description",
    "sv"."movement",
    "sv"."created_at"
   FROM ("public"."state_vectors" "sv"
     LEFT JOIN "public"."members" "m" ON (("m"."id" = "sv"."member_id")))
  ORDER BY "sv"."created_at" DESC;


--
-- Name: v_symbolic_telemetry_hourly; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_symbolic_telemetry_hourly" AS
 SELECT "date_trunc"('hour'::"text", "created_at") AS "hour_bucket",
    "domain",
    "authority",
    "prompt_role",
    "render_blocked",
    "block_reason",
    ("count"(*))::integer AS "event_count",
    ("count"(*) FILTER (WHERE "allowed_in_prompt"))::integer AS "prompt_eligible",
    ("count"(*) FILTER (WHERE "allowed_in_memory"))::integer AS "memory_eligible",
    ("count"(*) FILTER (WHERE "allowed_in_user_view"))::integer AS "user_view_eligible"
   FROM "public"."symbolic_telemetry_events"
  GROUP BY ("date_trunc"('hour'::"text", "created_at")), "domain", "authority", "prompt_role", "render_blocked", "block_reason"
  ORDER BY ("date_trunc"('hour'::"text", "created_at")) DESC, (("count"(*))::integer) DESC;


--
-- Name: v_threshold_timeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW "public"."v_threshold_timeline" AS
 SELECT "te"."id",
    "te"."member_id",
    "m"."name" AS "member_name",
    "te"."event_type",
    "te"."element",
    "te"."intensity",
    "te"."summary",
    "te"."source",
    "te"."created_at"
   FROM ("public"."threshold_events" "te"
     LEFT JOIN "public"."members" "m" ON (("m"."id" = "te"."member_id")))
  ORDER BY "te"."created_at" DESC;


