-- Name: workflow_enrollments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."workflow_enrollments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workflow_id" "uuid" NOT NULL,
    "contact_id" "uuid" NOT NULL,
    "current_step" integer DEFAULT 0,
    "next_action_at" timestamp with time zone,
    "status" character varying(20) DEFAULT 'active'::character varying,
    "steps_completed" "jsonb" DEFAULT '[]'::"jsonb",
    "entered_at" timestamp with time zone DEFAULT "now"(),
    "completed_at" timestamp with time zone,
    "exited_at" timestamp with time zone,
    "exit_reason" character varying(100)
);


--
-- Name: working_draft_revisions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."working_draft_revisions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "draft_id" "uuid" NOT NULL,
    "revision_number" integer NOT NULL,
    "content" "text" NOT NULL,
    "saved_by" "uuid" NOT NULL,
    "note" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "working_draft_revisions_revision_number_check" CHECK (("revision_number" > 0))
);


--
-- Name: world_experiments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."world_experiments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "world_id" "uuid" NOT NULL,
    "code" character varying(50) NOT NULL,
    "title" "text" NOT NULL,
    "description" "text" NOT NULL,
    "trigger_conditions" "text",
    "difficulty_level" character varying(20) DEFAULT 'accessible'::character varying,
    "instructions" "text",
    "what_to_notice" "text",
    "reflection_prompts" "text"[],
    "is_active" boolean DEFAULT true,
    "sort_order" integer DEFAULT 100,
    "created_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "world_experiments_difficulty_level_check" CHECK ((("difficulty_level")::"text" = ANY (ARRAY[('accessible'::character varying)::"text", ('intermediate'::character varying)::"text", ('advanced'::character varying)::"text"])))
);


--
-- Name: world_insight_types; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."world_insight_types" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "world_id" "uuid" NOT NULL,
    "code" character varying(50) NOT NULL,
    "display_name" "text" NOT NULL,
    "description" "text",
    "detection_markers" "text"[] DEFAULT '{}'::"text"[],
    "prompt_template" "text",
    "icon_name" character varying(50),
    "significance_default" numeric(3,2) DEFAULT 0.5,
    "is_active" boolean DEFAULT true,
    "sort_order" integer DEFAULT 100,
    "created_at" timestamp with time zone DEFAULT "now"()
);


--
-- Name: world_telemetry; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE "public"."world_telemetry" (
    "id" bigint NOT NULL,
    "session_id" "text",
    "member_id" "uuid",
    "event_type" "text" NOT NULL,
    "intent" "text",
    "world" "text",
    "confidence" real,
    "time_to_click" integer,
    "time_in_world" integer,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


