--
-- Name: active_patterns _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW "public"."active_patterns" AS
 SELECT "pl"."id",
    "pl"."member_id",
    "pl"."statement",
    "pl"."evidence_refs",
    "pl"."scope",
    "pl"."confidence",
    "pl"."status",
    "pl"."member_response",
    "pl"."member_response_at",
    "pl"."times_offered",
    "pl"."first_seen_at",
    "pl"."last_evidence_at",
    "pl"."last_offered_at",
    "pl"."retired_at",
    "pl"."retirement_reason",
    "pl"."created_at",
    "pl"."updated_at",
    "count"("pe"."id") AS "evidence_count",
    "max"("pe"."detected_at") AS "latest_evidence_at"
   FROM ("public"."pattern_ledger" "pl"
     LEFT JOIN "public"."pattern_evidence" "pe" ON (("pe"."pattern_id" = "pl"."id")))
  WHERE (("pl"."status" = ANY (ARRAY['emerging'::"text", 'confirmed'::"text", 'partial'::"text"])) AND ("pl"."confidence" >= 0.3))
  GROUP BY "pl"."id";


--
-- Name: v_rl_containers_needing_attention _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW "public"."v_rl_containers_needing_attention" AS
 SELECT "rc"."practice_id",
    "rc"."id" AS "container_id",
    "rc"."status",
    "rc"."scope",
    "rc"."updated_at",
    "max"("s"."scheduled_start_at") AS "last_session",
        CASE
            WHEN (("rc"."status" = 'closing'::"public"."container_status") AND (NOT (EXISTS ( SELECT 1
               FROM "public"."rl_sessions" "s2"
              WHERE (("s2"."container_id" = "rc"."id") AND ("s2"."status" = 'scheduled'::"public"."rl_session_status") AND ("s2"."scheduled_start_at" > "now"())))))) THEN 'closing_no_next_session'::"text"
            WHEN (("rc"."status" = 'active'::"public"."container_status") AND (("max"("s"."scheduled_start_at") IS NULL) OR ("max"("s"."scheduled_start_at") < ("now"() - '30 days'::interval)))) THEN 'no_recent_session'::"text"
            ELSE NULL::"text"
        END AS "attention_reason"
   FROM ("public"."rl_containers" "rc"
     LEFT JOIN "public"."rl_sessions" "s" ON ((("s"."container_id" = "rc"."id") AND ("s"."status" = 'completed'::"public"."rl_session_status"))))
  WHERE ("rc"."status" = ANY (ARRAY['active'::"public"."container_status", 'paused'::"public"."container_status", 'closing'::"public"."container_status"]))
  GROUP BY "rc"."id"
 HAVING ((("rc"."status" = 'closing'::"public"."container_status") AND (NOT (EXISTS ( SELECT 1
           FROM "public"."rl_sessions" "s2"
          WHERE (("s2"."container_id" = "rc"."id") AND ("s2"."status" = 'scheduled'::"public"."rl_session_status") AND ("s2"."scheduled_start_at" > "now"())))))) OR (("rc"."status" = 'active'::"public"."container_status") AND (("max"("s"."scheduled_start_at") IS NULL) OR ("max"("s"."scheduled_start_at") < ("now"() - '30 days'::interval)))));


--
-- Name: v_rooms_summary _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW "public"."v_rooms_summary" AS
 SELECT "r"."id",
    "r"."slug",
    "r"."name",
    "r"."description",
    "r"."purpose",
    "r"."room_type",
    "r"."element",
    "r"."status",
    "r"."join_policy",
    "r"."visibility",
    "r"."max_members",
    "count"("rm"."id") FILTER (WHERE ((("rm"."status")::"text" = 'present'::"text") AND ("rm"."left_at" IS NULL))) AS "present_count",
    "count"(DISTINCT "e"."id") FILTER (WHERE ((("e"."moderation_status")::"text" = 'visible'::"text") AND (("e"."retention_status")::"text" = 'active'::"text") AND ("e"."created_at" > ("now"() - '7 days'::interval)))) AS "events_this_week",
    "max"("e"."created_at") FILTER (WHERE ((("e"."moderation_status")::"text" = 'visible'::"text") AND (("e"."retention_status")::"text" = 'active'::"text"))) AS "last_activity_at"
   FROM (("public"."commons_rooms" "r"
     LEFT JOIN "public"."commons_room_members" "rm" ON (("rm"."room_id" = "r"."id")))
     LEFT JOIN "public"."commons_room_events" "e" ON (("e"."room_id" = "r"."id")))
  WHERE (("r"."status")::"text" = ANY (ARRAY[('active'::character varying)::"text", ('forming'::character varying)::"text"]))
  GROUP BY "r"."id";


